#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pin for the LED
#define LED_PIN 2

// Define the validity check range
#define VALIDITY_CHECK_MIN 0
#define VALIDITY_CHECK_MAX 1

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the LED state
int set_led_state(int state) {
    if (gpioWrite(LED_PIN, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", LED_PIN);
        return -1;
    }
    return 0;
}

// Function to perform the validity check
int is_valid(int value) {
    return (value >= VALIDITY_CHECK_MIN && value <= VALIDITY_CHECK_MAX);
}

int main() {
    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the LED pin as an output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Generate a random integer between 0 and 1
        int random_value = rand() % 2;

        // Perform the validity check
        if (is_valid(random_value)) {
            // Set the LED state
            if (set_led_state(random_value) != 0) {
                // Error setting LED state, but continue running
            } else {
                // Report the state to standard output
                printf("LED state: %d\n", random_value);
            }
        } else {
            fprintf(stderr, "Invalid value: %d\n", random_value);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0040  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DIS 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the I2C device
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the I2C device
int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure ADS1115 for single-ended AIN0, +/-4.096V, 128 SPS
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DIS;

    if (i2c_write_word(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Failed to write configuration register\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Start a single conversion
        config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DIS;
        if (i2c_write_word(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
            fprintf(stderr, "Failed to write configuration register\n");
            break;
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read the conversion result
        uint16_t conversion_value;
        if (i2c_read_word(i2c_fd, ADS1115_REG_CONVERT, &conversion_value) < 0) {
            fprintf(stderr, "Failed to read conversion result\n");
            break;
        }

        // Print the raw ADC value
        printf("ADC Value: %d\n", (int16_t)conversion_value);

        // Wait 0.5 seconds
        sleep(0.5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// MLX90614 I2C address
#define MLX90614_ADDR 0x5A

// MLX90614 register addresses
#define TA_REG 0x06
#define TO_REG 0x07

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read temperature from MLX90614
float read_temperature() {
    int raw_data;
    float temp_celsius;

    // Read raw temperature data from TO_REG
    raw_data = i2cReadWordData(i2c_handle, TO_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", raw_data);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw data to Celsius (see MLX90614 datasheet)
    temp_celsius = (float)raw_data * 0.02 - 273.15;

    return temp_celsius;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for read error
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(5);
    }

    // The following lines will never be reached because of the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

