    if (i2c_write_word(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Start a single conversion
        config = CONFIG_OS_SINGLE | CONFIG_MUX_AIN0_GND | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DIS;
