#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    long long timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0; // Indicate error
        }
    }
    start_tick = gpioTick();

    // Wait for echo to end
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0; // Indicate error
        }
    }
    end_tick = gpioTick();

    // Calculate pulse duration
    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin to low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Measure distance
        float distance = measure_distance();

        // Get current time
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Print distance with timestamp
        if (distance >= 0) {
            printf("[%04d-%02d-%02d %02d:%02d:%02d] Distance: %.2f cm\n",
                   timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                   timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, distance);
        } else {
            fprintf(stderr, "[%04d-%02d-%02d %02d:%02d:%02d] Error: Could not measure distance\n",
                   timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                   timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

// Define constants
#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi
#define ADS1115_ADDR 0x28    // ADS1115 I2C address
#define CONFIG_REG 0x01       // Configuration register address
#define CONVERSION_REG 0x00  // Conversion register address
#define REF_VOLTAGE 4.096     // Reference voltage (4.096V)
#define MAX_VOLTAGE 3.0       // Maximum valid voltage
#define MIN_VOLTAGE -3.0      // Minimum valid voltage

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the I2C device
int16_t read_ads1115(int fd, uint8_t reg) {
    uint8_t buf[2];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to write a 16-bit value to the I2C device
int write_ads1115(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }

    return 0;
}

// Function to configure the ADS1115
int configure_ads1115(int fd) {
    // Configure for single-ended AIN0, 4.096V range, continuous conversion, 128 SPS
    uint16_t config = 0x4003; // 0b0100000000000011
    if (write_ads1115(fd, CONFIG_REG, config) != 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        return -1;
    }
    return 0;
}

// Function to read the ADC value and convert to voltage
float read_adc_and_convert(int fd) {
    int16_t raw_value = read_ads1115(fd, CONVERSION_REG);
    if (raw_value == -1) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1.0;
    }

    // Convert raw value to voltage
    float voltage = (float)raw_value * REF_VOLTAGE / 32768.0;

    return voltage;
}

// Function to validate the voltage reading
int validate_voltage(float voltage) {
    if (voltage >= MIN_VOLTAGE && voltage <= MAX_VOLTAGE) {
        return 1; // Valid
    } else {
        return 0; // Invalid
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value and convert to voltage
        float voltage = read_adc_and_convert(i2c_fd);

        if (voltage != -1.0) {
            // Validate voltage
            if (validate_voltage(voltage)) {
                // Print voltage
                printf("Voltage: %.3f V\n", voltage);
            } else {
                fprintf(stderr, "Invalid voltage reading: %.3f V\n", voltage);
            }
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus (this will never be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

