    long elapsed_time;

    // Get the start time
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Read the GPIO pin value
    if (gpio_pin == GPIO_17) {
        value = gpiod_line_get_value(line_17);
    } else if (gpio_pin == GPIO_18) {
        value = gpiod_line_get_value(line_18);
    } else if (gpio_pin == GPIO_27) {
        value = gpiod_line_get_value(line_27);
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
        return -1;
    }

    // Get the end time
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate the elapsed time in milliseconds
    elapsed_time = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;

    // Check for errors
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d\n", gpio_pin);
        return -1;
    }

    // Return the reading
    return value;
}

// Function to check the validity of a reading
int check_validity(int gpio_pin, int reading) {
    int initial_reading = reading;
    int current_reading;
    struct timespec start, end;
    long elapsed_time;

    // Get the start time
    clock_get_time(CLOCK_MONOTONIC, &start);

    // Wait for a short period
    usleep(VALIDITY_THRESHOLD * 1000); // Convert milliseconds to microseconds

    // Get the end time
    clock_get_time(CLOCK_MONOTONIC, &end);

    // Calculate the elapsed time in milliseconds
    elapsed_time = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;

    // Read the GPIO pin value again
    if (gpio_pin == GPIO_17) {
        current_reading = gpiod_line_get_value(line_17);
    } else if (gpio_pin == GPIO_18) {
        current_reading = gpiod_line_get_value(line_18);
    } else if (gpio_pin == GPIO_27) {
        current_reading = gpiod_line_get_value(line_27);
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
        return 0; // Or some other error value
    }

    // Check for errors
    if (current_reading < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d for validity check\n", gpio_pin);
        return 0; // Or some other error value
    }

    // Check if the reading has changed
    if (current_reading != initial_reading) {
        fprintf(stderr, "Error: GPIO %d reading changed during validity check\n", gpio_pin);
        return 0;
    }

    // Check if the reading stayed the same for the entire validity period
    if (current_reading == initial_reading) {
        return 1;
    } else {
        return 0;
    }
}

