// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

// Function prototypes
void set_gpio_state(int gpio, int state);
void report_gpio_state(int gpio, int state);
void signal_handler(int signal);

// Global variable to track program state for signal handler
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to set the state of a GPIO pin
void set_gpio_state(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to report the state of a GPIO pin
void report_gpio_state(int gpio, int state) {
    printf("GPIO %d: %s\n", gpio, (state == 1) ? "HIGH" : "LOW");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set all GPIOs HIGH
        set_gpio_state(GPIO_4, 1);
        set_gpio_state(GPIO_17, 1);
        set_gpio_state(GPIO_22, 1);
        set_gpio_state(GPIO_27, 1);

        // Report the state of each GPIO
        report_gpio_state(GPIO_4, 1);
        report_gpio_state(GPIO_17, 1);
        report_gpio_state(GPIO_22, 1);
        report_gpio_state(GPIO_27, 1);

        // Wait for 2 seconds
        sleep(2);

        // Set all GPIOs LOW
        set_gpio_state(GPIO_4, 0);
        set_gpio_state(GPIO_17, 0);
        set_gpio_state(GPIO_22, 0);
        set_gpio_state(GPIO_27, 0);

        // Report the state of each GPIO
        report_gpio_state(GPIO_4, 0);
        report_gpio_state(GPIO_17, 0);
        report_gpio_state(GPIO_22, 0);
        report_gpio_state(GPIO_27, 0);

        // Wait for 2 seconds
        sleep(2);
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

