#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_OUTPUT 2
#define GPIO_INPUT 3

// Define validity check parameters
#define VALIDITY_CHECK_THRESHOLD 100
#define VALIDITY_CHECK_DELAY_MS 10

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the output GPIO state
int set_output_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error setting output state on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to read the input GPIO state and perform validity check
int read_input_state(int gpio) {
    int raw_value = gpioRead(gpio);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading input state on GPIO %d\n", gpio);
        return -1;
    }

    // Perform validity check
    int sum = 0;
    for (int i = 0; i < 10; i++) {
        sum += gpioRead(gpio);
        gpioDelay(VALIDITY_CHECK_DELAY_MS * 1000); // Delay in microseconds
    }
    if (abs(sum - (10 * raw_value)) > VALIDITY_CHECK_THRESHOLD) {
        fprintf(stderr, "Validity check failed for GPIO %d\n", gpio);
        return -1;
    }

    return raw_value;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_OUTPUT, PI_OUTPUT);
    gpioSetMode(GPIO_INPUT, PI_INPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set output state to HIGH
        if (set_output_state(GPIO_OUTPUT, 1) != 0) {
            break;
        }
        printf("Output GPIO %d set to HIGH\n", GPIO_OUTPUT);

        // Read input state
        int input_state = read_input_state(GPIO_INPUT);
        if (input_state == -1) {
            break;
        }
        printf("Input GPIO %d state: %d\n", GPIO_INPUT, input_state);

        // Set output state to LOW
        if (set_output_state(GPIO_OUTPUT, 0) != 0) {
            break;
        }
        printf("Output GPIO %d set to LOW\n", GPIO_OUTPUT);

        // Read input state again
        input_state = read_input_state(GPIO_INPUT);
        if (input_state == -1) {
            break;
        }
        printf("Input GPIO %d state: %d\n", GPIO_INPUT, input_state);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    gpioTerminate();
    printf("pigpio terminated\n");
    return 0;
}

