// Function to write a single byte to the I2C device
int i2c_write_byte(int fd, uint8_t data) {
    ssize_t bytes_written = write(fd, &data, 1);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature from the SI7021
int read_temperature(int fd, float *temperature) {
    uint8_t data[2];
    uint16_t raw_temperature;

    // Send the temperature measurement command
    if (i2c_write_byte(fd, SI7021_TEMP_CMD) != 0) {
        return -1;
    }

    // Wait for the measurement to complete (at least 50ms)
    usleep(50000);

    // Read the temperature data
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }

    // Convert the raw data to temperature
    raw_temperature = (data[0] << 8) | data[1];
    *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;

    return 0;
}

// Function to read humidity from the SI7021
int read_humidity(int fd, float *humidity) {
    uint8_t data[2];
    uint16_t raw_humidity;

    // Send the humidity measurement command
    if (i2c_write_byte(fd, SI7021_HUMID_CMD) != 0) {
        return -1;
    }

    // Wait for the measurement to complete (at least 50ms)
    usleep(50000);

    // Read the humidity data
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading humidity data: %s\n", strerror(errno));
        return -1;
    }

    // Convert the raw data to humidity
    raw_humidity = (data[0] << 8) | data[1];
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

int main() {
    int i2c_fd;
    float temperature, humidity;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read temperature and humidity
        if (read_temperature(i2c_fd, &temperature) == 0 && read_humidity(i2c_fd, &humidity) == 0) {
            // Validate the readings
            if (temperature >= -40.0 && temperature <= 125.0 && humidity >= 0.0 && humidity <= 100.0) {
                // Get the current time
                time(&current_time);
                time_info = localtime(&current_time);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

                // Print the readings with a timestamp
                printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
            } else {
                fprintf(stderr, "Invalid sensor readings: Temperature = %.2f, Humidity = %.2f\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

// Define the ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Define the ADS1115 configuration register values
#define ADS1115_CONFIG_DEFAULT 0x8383 // Single-shot mode, AIN0, +/-4.096V, 128 SPS, Disable comparator

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the I2C device
int i2c_write_word(int fd, unsigned char reg, unsigned short value) {
    unsigned char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the I2C device
int i2c_read_word(int fd, unsigned char reg, unsigned short *value) {
    unsigned char buf[2];

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to configure the ADS1115
int configure_ads1115(int fd) {
    unsigned short config = ADS1115_CONFIG_DEFAULT;
    if (i2c_write_word(fd, ADS1115_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        return -1;
    }
    return 0;
}

// Function to read the ADC value from the ADS1115
int read_adc(int fd, int *value) {
    unsigned short raw_value;
    if (i2c_read_word(fd, ADS1115_REG_CONVERT, &raw_value) != 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }

    // The ADS1115 returns a 16-bit value, but the 12-bit ADC data is only
    // present in the lower 12 bits.  Shift right to get the 12-bit value.
    *value = (int)(raw_value >> 4);

    // Sign extend the 12-bit value to a 32-bit integer.
    if (*value & 0x800) {
        *value |= 0xFFFFF000;
    }

    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure the ADS1115
    if (configure_ads1115(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Read the ADC value and print it to standard output
    int adc_value;
    for (int i = 0; i < 3; i++) {
        if (read_adc(i2c_fd, &adc_value) == 0) {
            printf("ADC Value: %d\n", adc_value);
        } else {
            fprintf(stderr, "Failed to read ADC value, exiting.\n");
            close(i2c_fd);
            return 1;
        }
        sleep(1);
    }

    // Close the I2C bus
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
