// Define GPIO pins
#define GPIO_8 8
#define GPIO_9 9
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_23 23
#define GPIO_24 24

// Define the number of cycles
#define NUM_CYCLES 256

// Define the chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_8, *line_9, *line_10, *line_11, *line_23, *line_24;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_8) gpiod_line_release(line_8);
    if (line_9) gpiod_line_release(line_9);
    if (line_10) gpiod_line_release(line_10);
    if (line_11) gpiod_line_release(line_11);
    if (line_23) gpiod_line_release(line_23);
    if (line_24) gpiod_line_release(line_24);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

int main()
{
    int i;
    int ret;
    struct gpiod_line_request_config config;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_8 = gpiod_chip_get_line(chip, GPIO_8);
    line_9 = gpiod_chip_get_line(chip, GPIO_9);
    line_10 = gpiod_chip_get_line(chip, GPIO_10);
    line_11 = gpiod_chip_get_line(chip, GPIO_11);
    line_23 = gpiod_chip_get_line(chip, GPIO_23);
    line_24 = gpiod_chip_get_line(chip, GPIO_24);

    if (!line_8 || !line_9 || !line_10 || !line_11 || !line_23 || !line_24) {
        perror("Error getting GPIO line");
        goto cleanup;
    }

    // Configure GPIO lines for output
    config.consumer = "gpio-control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line_8, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 8");
        goto cleanup;
    }

    ret = gpiod_line_request(line_9, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 9");
        goto cleanup;
    }

    ret = gpiod_line_request(line_10, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 10");
        goto cleanup;
    }

    ret = gpiod_line_request(line_11, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 11");
        goto cleanup;
    }

    ret = gpiod_line_request(line_23, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 23");
        goto cleanup;
    }

    ret = gpiod_line_request(line_24, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 24");
        goto cleanup;
    }

    // Main loop
    for (i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO values based on cycle number
        gpiod_line_set_value(line_8, (i >> 0) & 1);
        gpiod_line_set_value(line_9, (i >> 1) & 1);
        gpiod_line_set_value(line_10, (i >> 2) & 1);
        gpiod_line_set_value(line_11, (i >> 3) & 1);
        gpiod_line_set_value(line_23, (i >> 4) & 1);
        gpiod_line_set_value(line_24, (i >> 5) & 1);

        // Print the cycle number and GPIO values
        printf("Cycle: %d, GPIO 8: %d, GPIO 9: %d, GPIO 10: %d, GPIO 11: %d, GPIO 23: %d, GPIO 24: %d\n",
               i, (i >> 0) & 1, (i >> 1) & 1, (i >> 2) & 1, (i >> 3) & 1, (i >> 4) & 1, (i >> 5) & 1);

        // Delay for 100 milliseconds
        usleep(100000);
    }

    // Cleanup
cleanup:
    // Release GPIO lines
    if (line_8) gpiod_line_release(line_8);
    if (line_9) gpiod_line_release(line_9);
    if (line_10) gpiod_line_release(line_10);
    if (line_11) gpiod_line_release(line_11);
    if (line_23) gpiod_line_release(line_23);
    if (line_24) gpiod_line_release(line_24);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    return 0;
}

