        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to perform the validity check
int is_valid(int value) {
    return (value >= VALIDITY_CHECK_MIN && value <= VALIDITY_CHECK_MAX);
}

int main() {
    // Register the signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
