    if (gpiod_line_request_output(line, "rpi_gpio_control", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Generate a random integer between 0 and 100
        int random_value = rand() % 101;

        // Perform the validity check
        if (is_valid(random_value)) {
            // Set the GPIO line value
