#include <unistd.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_17, *line_18, *line_27;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_18) {
        gpiod_line_release(line_18);
    }
    if (line_27) {
        gpiod_line_release(line_27);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 50000000; // 0.05 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    line_27 = gpiod_chip_get_line(chip, GPIO_27);

    if (!line_17 || !line_18 || !line_27) {
        perror("Error getting GPIO line");
        if (line_17) gpiod_line_release(line_17);
        if (line_18) gpiod_line_release(line_18);
        if (line_27) gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_17, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_18, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_27, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 27");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO states
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 value");
            break;
        }
        ret = gpiod_line_set_value(line_18, 0);
        if (ret < 0) {
            perror("Error setting GPIO 18 value");
            break;
        }
        ret = gpiod_line_set_value(line_27, 1);
        if (ret < 0) {
            perror("Error setting GPIO 27 value");
            break;
        }

        // Get current time
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Print GPIO states with timestamp
        printf("[%04d-%02d-%02d %02d:%02d:%02d] GPIO 17: 1, GPIO 18: 0, GPIO 27: 1\n",
               timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
               timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

        // Sleep for 0.05 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup on error
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);
    gpiod_line_release(line_27);
    gpiod_chip_close(chip);

    return 1;
}

