#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_OUTPUT 2
#define GPIO_INPUT 3

// Define validity check parameters
#define VALIDITY_CHECK_THRESHOLD 100
#define VALIDITY_CHECK_DELAY_MS 10

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the digital input with validity check
int read_digital_input(int gpio_input) {
    int reading = gpioRead(gpio_input);
    int sum = 0;
    for (int i = 0; i < VALIDITY_CHECK_THRESHOLD; ++i) {
        if (gpioRead(gpio_input) == reading) {
            sum++;
        }
        gpioDelay(VALIDITY_CHECK_DELAY_MS * 1000); // Delay in microseconds
    }
    if (sum == VALIDITY_CHECK_THRESHOLD) {
        return reading;
    } else {
        fprintf(stderr, "Error: Invalid reading detected on GPIO %d\n", gpio_input);
        return -1; // Indicate an error
    }
}

// Function to set the digital output
void set_digital_output(int gpio_output, int value) {
    gpioWrite(gpio_output, value);
    printf("GPIO %d set to %d\n", gpio_output, value);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_OUTPUT, PI_OUTPUT);
    gpioSetMode(GPIO_INPUT, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int input_value = read_digital_input(GPIO_INPUT);
        if (input_value != -1) {
            set_digital_output(GPIO_OUTPUT, input_value);
        }
        gpioDelay(500000); // Delay for 0.5 seconds (500000 microseconds)
    }

    // Cleanup and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

