    gpioSetMode(GPIO_8, PI_OUTPUT);
    gpioSetMode(GPIO_9, PI_OUTPUT);
    gpioSetMode(GPIO_10, PI_OUTPUT);
    gpioSetMode(GPIO_11, PI_OUTPUT);

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set GPIO pins HIGH
        gpioWrite(GPIO_8, 1);
        gpioWrite(GPIO_9, 1);
        gpioWrite(GPIO_10, 1);
        gpioWrite(GPIO_11, 1);
