        gpioWrite(GPIO_9, 0);
        gpioWrite(GPIO_10, 0);
        gpioWrite(GPIO_11, 0);
        printf("GPIO 8: LOW, GPIO 9: LOW, GPIO 10: LOW, GPIO 11: LOW\n");

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
