#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

int setup_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // No data available
        } else {
            perror("Error reading from UART");
            return -1;
        }
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = setup_uart(UART_PORT);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[256];
    time_t rawtime;
    struct tm * timeinfo;

    while (program_running) {
        int bytes_read = read_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("[%s] %s\n", timestamp, buffer);
        } else if (bytes_read < 0) {
            program_running = 0; // Exit on read error
        }
        usleep(100000); // 100ms delay
    }

    close(uart_fd);
    fprintf(stderr, "UART port closed.\n");
    return EXIT_SUCCESS;
}

