// Function to read the GPIO line and perform the validity check
int read_gpio_with_validity_check() {
    int value, i;
    struct timespec delay = {0, VALIDITY_CHECK_DELAY_MS * 1000000L}; // 100ms

    for (i = 0; i < VALIDITY_CHECK_READ_COUNT; i++) {
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line: %d\n", value);
            return -1; // Indicate error
        }
        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid GPIO value: %d\n", value);
            return -1; // Indicate error
        }
        nanosleep(&delay, NULL);
    }

    // If all reads were valid, return the last read value
    return value;
}

