// Define validity check range
#define VALIDITY_CHECK_MIN 0
#define VALIDITY_CHECK_MAX 1

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_2, *line_3;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_2) {
        gpiod_line_release(line_2);
    }
    if (line_3) {
        gpiod_line_release(line_3);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set GPIO value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to get GPIO value
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO value: %d\n", value);
        return -1;
    }
    return value;
}

// Function to perform validity check
int is_valid(int value) {
    return (value >= VALIDITY_CHECK_MIN && value <= VALIDITY_CHECK_MAX);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line_2) {
        perror("Error getting GPIO line 2");
        gpiod_chip_close(chip);
        return 1;
    }

    line_3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line_3) {
        perror("Error getting GPIO line 3");
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_2, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line 2 for output");
        gpiod_line_release(line_3);
