        perror("Error requesting GPIO line 3 for output");
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Get current time
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        // Get GPIO 2 value
        int value_2 = get_gpio_value(line_2);
        if (value_2 < 0) {
            continue; // Skip to next iteration if get_gpio_value fails
        }

        // Get GPIO 3 value
        int value_3 = get_gpio_value(line_3);
        if (value_3 < 0) {
            continue; // Skip to next iteration if get_gpio_value fails
        }

        // Perform validity check
        if (is_valid(value_2) && is_valid(value_3)) {
            // Report state
            printf("%s - GPIO 2: %d, GPIO 3: %d\n", buf, value_2, value_3);
        } else {
            fprintf(stderr, "%s - Invalid GPIO value(s) detected. Skipping report.\n", buf);
        }

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

