#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_OUTPUT 2
#define GPIO_INPUT 3

// Define validity check parameters
#define VALIDITY_CHECK_THRESHOLD 500
#define VALIDITY_CHECK_DELAY_MS 100

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the output GPIO state
int set_output_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error setting output state on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to read the input GPIO state and perform validity check
int read_input_state(int gpio) {
    int reading = gpioRead(gpio);
    if (reading < 0) {
        fprintf(stderr, "Error reading input state on GPIO %d\n", gpio);
        return -1;
    }

    // Perform validity check
    int sum = 0;
    for (int i = 0; i < 10; i++) {
        sum += gpioRead(gpio);
        gpioDelay(VALIDITY_CHECK_DELAY_MS);
    }
    if (abs(sum - (10 * reading)) > VALIDITY_CHECK_THRESHOLD) {
        fprintf(stderr, "Validity check failed for GPIO %d\n", gpio);
        return -1;
    }

    return reading;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_OUTPUT, PI_OUTPUT);
    gpioSetMode(GPIO_INPUT, PI_INPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set output state to HIGH
        if (set_output_state(GPIO_OUTPUT, 1) != 0) {
            break;
        }
        printf("Output GPIO %d set to HIGH\n", GPIO_OUTPUT);

        // Read input state
        int input_state = read_input_state(GPIO_INPUT);
        if (input_state == -1) {
            break;
        }
        printf("Input GPIO %d state: %d\n", GPIO_INPUT, input_state);

        // Set output state to LOW
        if (set_output_state(GPIO_OUTPUT, 0) != 0) {
            break;
        }
        printf("Output GPIO %d set to LOW\n", GPIO_OUTPUT);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define number of cycles
#define NUM_CYCLES 3

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_2, *line_3;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line_2) gpiod_line_release(line_2);
    if (line_3) gpiod_line_release(line_3);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO output: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to get GPIO input
int get_gpio_input(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO input: %d\n", value);
        return -1;
    }
    return value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO lines
    line_2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line_2) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_2);
        gpiod_chip_close(chip);
        return 1;
    }

    line_3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line_3) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_3);
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    int ret = gpiod_line_request_output(line_2, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %d\n", GPIO_2, ret);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_3, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %d\n", GPIO_3, ret);
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (int i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO 2 HIGH
        if (set_gpio_output(line_2, 1) < 0) {
            gpiod_line_release(line_2);
            gpiod_line_release(line_3);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d: HIGH\n", GPIO_2);
        sleep(1);

        // Set GPIO 2 LOW
        if (set_gpio_output(line_2, 0) < 0) {
            gpiod_line_release(line_2);
            gpiod_line_release(line_3);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d: LOW\n", GPIO_2);
        sleep(1);

        // Set GPIO 3 HIGH
        if (set_gpio_output(line_3, 1) < 0) {
            gpiod_line_release(line_2);
            gpiod_line_release(line_3);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d: HIGH\n", GPIO_3);
        sleep(1);

        // Set GPIO 3 LOW
        if (set_gpio_output(line_3, 0) < 0) {
            gpiod_line_release(line_2);
            gpiod_line_release(line_3);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d: LOW\n", GPIO_3);
        sleep(1);
    }

    // Cleanup
    gpiod_line_release(line_2);
    gpiod_line_release(line_3);
    gpiod_chip_close(chip);

    return 0;
}

