#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Main loop to toggle the GPIO pins
    while (program_running) {
        // Set all pins HIGH
        gpioWrite(GPIO_4, 1);
        gpioWrite(GPIO_17, 1);
        gpioWrite(GPIO_22, 1);
        gpioWrite(GPIO_27, 1);
        printf("GPIO 4: HIGH, GPIO 17: HIGH, GPIO 22: HIGH, GPIO 27: HIGH\n");
        sleep(1);

        // Set all pins LOW
        gpioWrite(GPIO_4, 0);
        gpioWrite(GPIO_17, 0);
        gpioWrite(GPIO_22, 0);
        gpioWrite(GPIO_27, 0);
        printf("GPIO 4: LOW, GPIO 17: LOW, GPIO 22: LOW, GPIO 27: LOW\n");
        sleep(1);
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the GPIO chip and line number
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

// Global variables for GPIO line and chip
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    if (gpiod_line_request_output(line, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to toggle the GPIO line
    while (1) {
        // Set the GPIO line to HIGH
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Error setting GPIO line to HIGH");
            break;
        }
        printf("GPIO %d: HIGH\n", GPIO_LINE);

        // Wait for 0.5 seconds
        struct timespec delay = {0, 500000000L}; // 0 seconds, 500 milliseconds
        nanosleep(&delay, NULL);

        // Set the GPIO line to LOW
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Error setting GPIO line to LOW");
            break;
        }
        printf("GPIO %d: LOW\n", GPIO_LINE);

        // Wait for 0.5 seconds
        nanosleep(&delay, NULL);
    }

    // Clean up resources before exiting
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define validity check parameters
#define VALIDITY_CHECK_DELAY_MS 100
#define VALIDITY_CHECK_THRESHOLD 500 // milliseconds

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_17, *line_18;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line_17) gpiod_line_release(line_17);
    if (line_18) gpiod_line_release(line_18);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO state: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(struct gpiod_line *line) {
    int ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO state: %d\n", ret);
        return -1;
    }
    return ret;
}

// Function to perform validity check
int perform_validity_check(struct gpiod_line *line) {
    struct timespec start, end;
    int initial_state, final_state;

    // Get initial state
    initial_state = get_gpio_state(line);
    if (initial_state < 0) return -1;

    // Set to a different state
    if (set_gpio_state(line, !initial_state) < 0) return -1;

    // Wait for a short period
    usleep(VALIDITY_CHECK_DELAY_MS * 1000); // Convert ms to microseconds

    // Get final state
    final_state = get_gpio_state(line);
    if (final_state < 0) return -1;

    // Restore initial state
    if (set_gpio_state(line, initial_state) < 0) return -1;

    // Check if the state changed
    if (final_state == initial_state) {
        return 0; // Valid
    } else {
        return -1; // Invalid
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO lines
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line_17) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_17);
        gpiod_chip_close(chip);
        return 1;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line_18) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_18);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_17, "app", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output\n", GPIO_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line_18, "app", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output\n", GPIO_18);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Perform validity check for GPIO 17
    printf("Performing validity check for GPIO %d...\n", GPIO_17);
    if (perform_validity_check(line_17) < 0) {
        fprintf(stderr, "GPIO %d failed validity check\n", GPIO_17);
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO %d passed validity check\n", GPIO_17);

    // Perform validity check for GPIO 18
    printf("Performing validity check for GPIO %d...\n", GPIO_18);
    if (perform_validity_check(line_18) < 0) {
        fprintf(stderr, "GPIO %d failed validity check\n", GPIO_18);
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO %d passed validity check\n", GPIO_18);

    // Set GPIO 17 to HIGH
    if (set_gpio_state(line_17, 1) < 0) {
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO %d set to HIGH\n", GPIO_17);

    // Set GPIO 18 to LOW
    if (set_gpio_state(line_18, 0) < 0) {
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO %d set to LOW\n", GPIO_18);

    // Release GPIO lines and close chip
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define the GPIO pin number (BCM numbering)
#define GPIO_PIN 4

// Define the number of GPIO lines
#define NUM_LINES 1

// Define the number of retries for DHT11 communication
#define MAX_RETRIES 3

// Define the timeout in milliseconds
#define TIMEOUT_MS 100

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

// Structure to hold DHT11 data
typedef struct {
    uint8_t humidity_int;
    uint8_t humidity_dec;
    uint8_t temperature_int;
    uint8_t temperature_dec;
    uint8_t checksum;
} dht11_data_t;

// Signal handler for graceful shutdown
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int init_gpio(int pin)
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "dht11_reader";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read data from the DHT11 sensor
int read_dht11(dht11_data_t *data)
{
    int i, j;
    uint8_t raw_data[40];

    // Send start signal
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    usleep(18000); // 18ms

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    usleep(20); // 20us

    // Prepare to receive data
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    // Wait for the DHT11 to pull the line low (response signal)
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(line) > 0) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if ((now.tv_sec - start.tv_sec) * 1000 + (now.tv_nsec - start.tv_nsec) / 1000000 > TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for DHT11 response signal.\n");
            return -1;
        }
    }

    // Wait for the DHT11 to pull the line high (response signal)
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(line) < 0) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if ((now.tv_sec - start.tv_sec) * 1000 + (now.tv_nsec - start.tv_nsec) / 1000000 > TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for DHT11 response signal.\n");
            return -1;
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the line to go low
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) > 0) {
            clock_gettime(CLOCK_MONOTONIC, &now);
            if ((now.tv_sec - start.tv_sec) * 1000 + (now.tv_nsec - start.tv_nsec) / 1000000 > TIMEOUT_MS) {
                fprintf(stderr, "Timeout waiting for data bit low.\n");
                return -1;
            }
        }

        // Measure the length of the high pulse
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) < 0) {
            clock_gettime(CLOCK_MONOTONIC, &now);
            if ((now.tv_sec - start.tv_sec) * 1000 + (now.tv_nsec - start.tv_nsec) / 1000000 > TIMEOUT_MS) {
                fprintf(stderr, "Timeout waiting for data bit high.\n");
                return -1;
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &now);
        long pulse_length = (now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000;

        // Determine if the bit is 0 or 1 based on the pulse length
        raw_data[i] = (pulse_length > 40) ? 1 : 0; // Adjust threshold as needed
    }

    // Convert raw data to meaningful values
    data->humidity_int = 0;
    data->humidity_dec = 0;
    data->temperature_int = 0;
    data->temperature_dec = 0;
    data->checksum = 0;

    for (i = 0; i < 8; i++) {
        data->humidity_int |= (raw_data[i] << (7 - i));
    }
    for (i = 8; i < 16; i++) {
        data->humidity_dec |= (raw_data[i] << (15 - i));
    }
    for (i = 16; i < 24; i++) {
        data->temperature_int |= (raw_data[i] << (23 - i));
    }
    for (i = 24; i < 32; i++) {
        data->temperature_dec |= (raw_data[i] << (31 - i));
    }
    for (i = 32; i < 40; i++) {
        data->checksum |= (raw_data[i] << (39 - i));
    }

    return 0;
}

// Function to validate the DHT11 data
int validate_dht11_data(const dht11_data_t *data)
{
    uint8_t checksum = (data->humidity_int + data->humidity_dec + data->temperature_int + data->temperature_dec) & 0xFF;
    if (checksum != data->checksum) {
        fprintf(stderr, "Checksum error: calculated %u, received %u\n", checksum, data->checksum);
        return -1;
    }

    // Basic range checks (adjust as needed for your environment)
    if (data->humidity_int > 100 || data->temperature_int > 50) {
        fprintf(stderr, "Invalid data: humidity = %u, temperature = %u\n", data->humidity_int, data->temperature_int);
        return -1;
    }

    return 0;
}

// Function to print the DHT11 data
void print_dht11_data(const dht11_data_t *data)
{
    printf("Humidity: %u.%u %%\n", data->humidity_int, data->humidity_dec);
    printf("Temperature: %u.%u °C\n", data->temperature_int, data->temperature_dec);
}

int main()
{
    int retries = 0;
    dht11_data_t dht11_data;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read DHT11 data
        if (read_dht11(&dht11_data) == 0) {
            // Validate DHT11 data
            if (validate_dht11_data(&dht11_data) == 0) {
                // Print DHT11 data
                print_dht11_data(&dht11_data);
                retries = 0; // Reset retries on successful read
            } else {
                fprintf(stderr, "Invalid DHT11 data. Retrying...\n");
                retries++;
            }
        } else {
            fprintf(stderr, "Failed to read DHT11 data. Retrying...\n");
            retries++;
        }

        // Check for maximum retries
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Maximum retries reached. Exiting.\n");
            break;
        }

        // Wait before next attempt
        usleep(1000000); // 1 second
    }

    // Release GPIO resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return (retries >= MAX_RETRIES) ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_17, *line_18, *line_27;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_18) {
        gpiod_line_release(line_18);
    }
    if (line_27) {
        gpiod_line_release(line_27);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line_17) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line_18) {
        perror("Error getting GPIO line 18");
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    line_27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line_27) {
        perror("Error getting GPIO line 27");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_17, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 for output");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_18, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18 for output");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_27, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 27 for output");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO values
    ret = gpiod_line_set_value(line_17, 1);
    if (ret < 0) {
        perror("Error setting GPIO line 17 value");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_set_value(line_18, 0);
    if (ret < 0) {
        perror("Error setting GPIO line 18 value");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_set_value(line_27, 1);
    if (ret < 0) {
        perror("Error setting GPIO line 27 value");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Print GPIO values
    printf("GPIO %d: %d\n", GPIO_17, gpiod_line_get_value(line_17));
    printf("GPIO %d: %d\n", GPIO_18, gpiod_line_get_value(line_18));
    printf("GPIO %d: %d\n", GPIO_27, gpiod_line_get_value(line_27));

    // Release GPIO lines
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);
    gpiod_line_release(line_27);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define validity check range
#define VALIDITY_CHECK_MIN 0
#define VALIDITY_CHECK_MAX 100

// Define number of cycles
#define NUM_CYCLES 3

// Define cycle delay (seconds)
#define CYCLE_DELAY 5

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_2, *line_3;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line_2) {
        gpiod_line_release(line_2);
    }
    if (line_3) {
        gpiod_line_release(line_3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to set GPIO value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to get GPIO value
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO value: %s\n", strerror(-value));
        return -1;
    }
    return value;
}

// Function to perform validity check
int perform_validity_check(int value) {
    return (value >= VALIDITY_CHECK_MIN && value <= VALIDITY_CHECK_MAX);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line_2) {
        perror("Error getting GPIO line 2");
        gpiod_chip_close(chip);
        return 1;
    }

    line_3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line_3) {
        perror("Error getting GPIO line 3");
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    int ret = gpiod_line_request_output(line_2, "gpio-control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line 2 for output: %s\n", strerror(-ret));
        gpiod_line_release(line_3);
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_3, "gpio-control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line 3 for output: %s\n", strerror(-ret));
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (int i = 0; i < NUM_CYCLES; i++) {
        // GPIO 2: Set to 1
        if (set_gpio_value(line_2, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 2 to 1\n");
            break;
        }
        printf("GPIO 2: 1\n");

        // GPIO 3: Get value and perform validity check
        int value_3 = get_gpio_value(line_3);
        if (value_3 < 0) {
            fprintf(stderr, "Error getting GPIO 3 value\n");
            break;
        }

        if (!perform_validity_check(value_3)) {
            fprintf(stderr, "GPIO 3 value %d is out of range (%d-%d)\n", value_3, VALIDITY_CHECK_MIN, VALIDITY_CHECK_MAX);
            break;
        }
        printf("GPIO 3: %d (valid)\n", value_3);

        // Delay
        sleep(CYCLE_DELAY);

        // GPIO 2: Set to 0
        if (set_gpio_value(line_2, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 2 to 0\n");
            break;
        }
        printf("GPIO 2: 0\n");

        // GPIO 3: Set to 1
        if (set_gpio_value(line_3, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 3 to 1\n");
            break;
        }
        printf("GPIO 3: 1\n");

        // Delay
        sleep(CYCLE_DELAY);

        // GPIO 2: Set to 1
        if (set_gpio_value(line_2, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 2 to 1\n");
            break;
        }
        printf("GPIO 2: 1\n");

        // GPIO 3: Set to 0
        if (set_gpio_value(line_3, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 3 to 0\n");
            break;
        }
        printf("GPIO 3: 0\n");

        // Delay
        sleep(CYCLE_DELAY);
    }

    // Cleanup
    gpiod_line_release(line_2);
    gpiod_line_release(line_3);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_2, *line_3, *line_17;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_2) gpiod_line_release(line_2);
    if (line_3) gpiod_line_release(line_3);
    if (line_17) gpiod_line_release(line_17);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

int main() {
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_2 = gpiod_chip_get_line(chip, GPIO_2);
    line_3 = gpiod_chip_get_line(chip, GPIO_3);
    line_17 = gpiod_chip_get_line(chip, GPIO_17);

    if (!line_2 || !line_3 || !line_17) {
        perror("Error getting GPIO line");
        goto cleanup;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_2, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 2");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line_3, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 3");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line_17, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Get current time
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        // Set GPIO states
        ret = gpiod_line_set_value(line_2, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 2 value");
            goto cleanup;
        }

        ret = gpiod_line_set_value(line_3, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 3 value");
            goto cleanup;
        }

        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 17 value");
            goto cleanup;
        }

        // Print state to standard output
        printf("%s: GPIO %d: 1, GPIO %d: 0, GPIO %d: 1\n", buf, GPIO_2, GPIO_3, GPIO_17);

        // Wait 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

cleanup:
    // Release GPIO lines
    if (line_2) gpiod_line_release(line_2);
    if (line_3) gpiod_line_release(line_3);
    if (line_17) gpiod_line_release(line_17);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    return 1;
}

