#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define the GPIO pins to control
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_27 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Main loop to toggle the GPIO pins
    while (!terminate) {
        // Set all GPIOs HIGH
        gpioWrite(GPIO_4, 1);
        gpioWrite(GPIO_17, 1);
        gpioWrite(GPIO_18, 1);
        gpioWrite(GPIO_22, 1);
        gpioWrite(GPIO_27, 1);
        printf("GPIO 4: %d, GPIO 17: %d, GPIO 18: %d, GPIO 22: %d, GPIO 27: %d\n", 1, 1, 1, 1, 1);
        gpioDelay(50000); // 0.05 seconds

        // Set all GPIOs LOW
        gpioWrite(GPIO_4, 0);
        gpioWrite(GPIO_17, 0);
        gpioWrite(GPIO_18, 0);
        gpioWrite(GPIO_22, 0);
        gpioWrite(GPIO_27, 0);
        printf("GPIO 4: %d, GPIO 17: %d, GPIO 18: %d, GPIO 22: %d, GPIO 27: %d\n", 0, 0, 0, 0, 0);
        gpioDelay(50000); // 0.05 seconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the GPIO chip and line number
#define GPIOCHIP "gpiochip0"
#define GPIO_LINE 8

// Global variables for GPIO line and chip
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 0.01 seconds

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Set the GPIO line to HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO line to HIGH");
            break;
        }
        printf("GPIO %d: HIGH\n", GPIO_LINE);

        // Sleep for 0.01 seconds
        nanosleep(&sleep_time, NULL);

        // Set the GPIO line to LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO line to LOW");
            break;
        }
        printf("GPIO %d: LOW\n", GPIO_LINE);

        // Sleep for 0.01 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up resources before exiting
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 1;
}

