    int value;
    struct timespec delay;

    // Set up the delay
    delay.tv_sec = 0;
    delay.tv_nsec = DELAY_MS * 1000000; // Convert milliseconds to nanoseconds

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
