                gpiod_chip_close(chip);
                return 1;
            }
            printf("GPIO %d: 1\n", gpios[i]);
        }

        // Wait for 0.05 seconds
        nanosleep(&sleep_time, NULL);

        // Toggle the GPIO lines back to 0
        for (int i = 0; i < 9; i++) {
            ret = gpiod_line_set_value(lines[i], 0);
