#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define OPT3001_ADDR 0x44

// Define the register addresses
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the I2C device
int read_i2c_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Function to write a 16-bit value to the I2C device
int write_i2c_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure the OPT3001 for continuous conversion mode
    if (write_i2c_word(i2c_fd, CONFIG_REG, 0xCB01) < 0) {
        fprintf(stderr, "Failed to configure OPT3001\n");
        close(i2c_fd);
        return 1;
    }

    // Read the result register
    int result = read_i2c_word(i2c_fd, RESULT_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read result register\n");
        close(i2c_fd);
        return 1;
    }

    // Extract the exponent and result from the raw data
    int exponent = (result >> 12) & 0x0F;
    int result_raw = result & 0x0FFF;

    // Calculate the voltage
    float voltage = 0.01 * result_raw * (1 << exponent);

    // Print the voltage
    printf("Voltage: %.2f V\n", voltage);

    // Close the I2C bus
    close(i2c_fd);

    return 0;
}

