#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <gpiod.h>

// Define GPIO chip and line
#define GPIOCHIP "gpiochip0"
#define GPIO_LINE 18

// Define validity check parameters
#define VALIDITY_CHECK_DELAY_MS 100
#define VALIDITY_CHECK_THRESHOLD_MS 50

// Global variables for GPIO line and chip
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int gpio_init(void);
int gpio_set_output(int value);
int gpio_read_input(void);
int gpio_validity_check(int value);
void gpio_cleanup(void);
void signal_handler(int sig);

// Signal handler for graceful exit
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    gpio_cleanup();
    exit(0);
}

// Initialize GPIO line
int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Set GPIO output value
int gpio_set_output(int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO output value");
        return -1;
    }
    return 0;
}

// Read GPIO input value
int gpio_read_input(void) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO input value");
        return -1;
    }
    return value;
}

// Perform validity check
int gpio_validity_check(int value) {
    struct timeval start, end;
    int duration_ms;

    gettimeofday(&start, NULL);
    usleep(VALIDITY_CHECK_DELAY_MS * 1000); // Delay in microseconds
    gettimeofday(&end, NULL);

    duration_ms = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec - start.tv_usec) / 1000;

    if (duration_ms < VALIDITY_CHECK_THRESHOLD_MS) {
        return 0; // Invalid
    }

    return 1; // Valid
}

// Cleanup GPIO resources
void gpio_cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Set GPIO output to HIGH
    if (gpio_set_output(1) < 0) {
        fprintf(stderr, "Failed to set GPIO output HIGH. Exiting.\n");
        gpio_cleanup();
        return 1;
    }
    printf("GPIO output set to HIGH\n");

    // Read GPIO input
    int input_value = gpio_read_input();
    if (input_value < 0) {
        fprintf(stderr, "Failed to read GPIO input. Exiting.\n");
        gpio_cleanup();
        return 1;
    }
    printf("GPIO input read: %d\n", input_value);

    // Perform validity check
    if (gpio_validity_check(input_value) == 0) {
        fprintf(stderr, "GPIO input invalid according to validity check. Exiting.\n");
        gpio_cleanup();
        return 1;
    }
    printf("GPIO input validated\n");

    // Cleanup and exit
    gpio_cleanup();
    return 0;
}

