    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO state: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(struct gpiod_line *line) {
    int ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO state: %d\n", ret);
        return -1;
    }
