#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Set GPIO 17 HIGH, GPIO 18 LOW
        gpioWrite(GPIO_17, 1);
        gpioWrite(GPIO_18, 0);
        printf("GPIO 17: HIGH, GPIO 18: LOW\n");

        // Wait for 0.5 seconds
        time_sleep(0.5);

        // Set GPIO 17 LOW, GPIO 18 HIGH
        gpioWrite(GPIO_17, 0);
        gpioWrite(GPIO_18, 1);
        printf("GPIO 17: LOW, GPIO 18: HIGH\n");

        // Wait for 0.5 seconds
        time_sleep(0.5);
    }

    // Clean up and exit
    gpioWrite(GPIO_17, 0); // Ensure GPIO 17 is LOW before exiting
    gpioWrite(GPIO_18, 0); // Ensure GPIO 18 is LOW before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define TIMEOUT_SEC 1

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

int setup_uart(const char *port) {
    struct termios tty;

    uart_fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd < 0) {
        perror("Error opening UART port");
        return -1;
    }

    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 115200 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = TIMEOUT_SEC * 10; // Timeout in deciseconds

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return -1;
    }

    return 0;
}

int read_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read < 0) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        fprintf(stderr, "Timeout reading from UART\n");
        return 0; // Timeout
    }
    buffer[bytes_read] = '\0';
    return bytes_read;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_uart(UART_PORT) != 0) {
        return EXIT_FAILURE;
    }

    char buffer[256];
    int bytes_read;

    while (program_running) {
        bytes_read = read_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("%s", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading data, exiting.\n");
            break;
        }
        // Add a small delay to avoid busy-waiting
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    close(uart_fd);
    return EXIT_SUCCESS;
}

