// Define GPIO pins
#define GPIO_11 11
#define GPIO_12 12
#define GPIO_17 17
#define GPIO_18 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stdout, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_11, PI_OUTPUT);
    gpioSetMode(GPIO_12, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Apply HIGH state to GPIO pins
        gpioWrite(GPIO_11, 1);
        gpioWrite(GPIO_12, 1);
        gpioWrite(GPIO_17, 1);
        gpioWrite(GPIO_18, 1);

        // Print HIGH state to standard output
        printf("GPIO %d: HIGH\n", GPIO_11);
        printf("GPIO %d: HIGH\n", GPIO_12);
        printf("GPIO %d: HIGH\n", GPIO_17);
        printf("GPIO %d: HIGH\n", GPIO_18);

        // Delay for 0.1 seconds
        time_sleep(0.1);

        // Apply LOW state to GPIO pins
        gpioWrite(GPIO_11, 0);
        gpioWrite(GPIO_12, 0);
        gpioWrite(GPIO_17, 0);
        gpioWrite(GPIO_18, 0);

        // Print LOW state to standard output
        printf("GPIO %d: LOW\n", GPIO_11);
        printf("GPIO %d: LOW\n", GPIO_12);
        printf("GPIO %d: LOW\n", GPIO_17);
        printf("GPIO %d: LOW\n", GPIO_18);

        // Delay for 0.1 seconds
        time_sleep(0.1);
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

