#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_OUTPUT 2
#define GPIO_INPUT 3

// Define validity check parameters
#define VALIDITY_CHECK_THRESHOLD 500
#define VALIDITY_CHECK_WINDOW 1000000 // 1 second in microseconds

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the output GPIO state
int set_output_state(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error setting output state on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to read the input GPIO state and perform validity check
int read_input_state(int gpio) {
    int raw_value = gpioRead(gpio);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading input state on GPIO %d\n", gpio);
        return -1;
    }

    // Perform validity check
    if (raw_value < VALIDITY_CHECK_THRESHOLD || raw_value > (1000 - VALIDITY_CHECK_THRESHOLD)) {
        fprintf(stderr, "Invalid reading detected on GPIO %d: %d\n", gpio, raw_value);
        return -1; // Indicate invalid reading
    }

    return raw_value;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_OUTPUT, PI_OUTPUT);
    gpioSetMode(GPIO_INPUT, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set output state to HIGH
        if (set_output_state(GPIO_OUTPUT, 1) != 0) {
            break; // Exit loop on error
        }
        printf("Output GPIO %d set to HIGH\n", GPIO_OUTPUT);

        // Read input state
        int input_value = read_input_state(GPIO_INPUT);
        if (input_value == -1) {
            // Continue to the next iteration if the reading is invalid
            continue;
        }

        // Set output state to LOW
        if (set_output_state(GPIO_OUTPUT, 0) != 0) {
            break; // Exit loop on error
        }
        printf("Output GPIO %d set to LOW\n", GPIO_OUTPUT);

        // Delay for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

