int main() {
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line 17
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line_17) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line 18
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line_18) {
        perror("Error getting GPIO line 18");
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 17 as output
    ret = gpiod_line_request_output(line_17, "rpi_gpio_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 as output");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 18 as output
    ret = gpiod_line_request_output(line_18, "rpi_gpio_control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18 as output");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Get current time
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        // Set GPIO 17 to HIGH
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 to HIGH");
            break;
        }

        // Set GPIO 18 to LOW
        ret = gpiod_line_set_value(line_18, 0);
        if (ret < 0) {
            perror("Error setting GPIO 18 to LOW");
            break;
        }

        // Print state to standard output
        printf("GPIO 17: HIGH, GPIO 18: LOW, Time: %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

        // Wait 0.05 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 0.05 seconds
        nanosleep(&sleep_time, NULL);

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Set GPIO 17 to LOW
        ret = gpiod_line_set_value(line_17, 0);
        if (ret < 0) {
            perror("Error setting GPIO 17 to LOW");
            break;
        }

        // Set GPIO 18 to HIGH
        ret = gpiod_line_set_value(line_18, 1);
        if (ret < 0) {
            perror("Error setting GPIO 18 to HIGH");
            break;
        }

        // Print state to standard output
        printf("GPIO 17: LOW, GPIO 18: HIGH, Time: %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

        // Wait 0.05 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 1;
}

#include <stdio.h>
