// Define GPIO pins
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

// Define PWM range
#define PWM_RANGE 1000

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycle (50%)
        int duty_cycle = PWM_RANGE / 2;

        // Apply PWM values
        gpioPWM(PWM_PIN_1, duty_cycle);
        gpioPWM(PWM_PIN_2, duty_cycle);
