#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define MAX_SENSORS 10
#define MAX_SENSOR_ID_LENGTH 20
#define MAX_PATH_LENGTH 100
#define TEMP_FILE "w1_slave"
#define ERROR_TEMP -999.0

// Global variable to track program termination for signal handling
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor information
typedef struct {
    char id[MAX_SENSOR_ID_LENGTH];
    char path[MAX_PATH_LENGTH];
} sensor_t;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signum) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to discover DS18B20 sensors
int discover_sensors(sensor_t sensors[], int max_sensors) {
    DIR *dir;
    struct dirent *ent;
    int sensor_count = 0;

    dir = opendir("/sys/bus/w1/devices/");
    if (dir == NULL) {
        perror("Error opening /sys/bus/w1/devices/");
        return -1;
    }

    while ((ent = readdir(dir)) != NULL && sensor_count < max_sensors) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            snprintf(sensors[sensor_count].id, MAX_SENSOR_ID_LENGTH, "%s", ent->d_name);
            snprintf(sensors[sensor_count].path, MAX_PATH_LENGTH, "/sys/bus/w1/devices/%s/%s", ent->d_name, TEMP_FILE);
            sensor_count++;
        }
    }

    closedir(dir);
    return sensor_count;
}

// Function to read temperature from a sensor
float read_temperature(const char *sensor_path) {
    int fd;
    char buffer[256];
    ssize_t bytes_read;
    char *temp_str;
    float temperature = ERROR_TEMP;

    fd = open(sensor_path, O_RDONLY);
    if (fd == -1) {
        perror("Error opening temperature file");
        return ERROR_TEMP;
    }

    bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read == -1) {
        perror("Error reading temperature file");
        close(fd);
        return ERROR_TEMP;
    }
    buffer[bytes_read] = '\0';

    close(fd);

    temp_str = strstr(buffer, "t=");
    if (temp_str != NULL) {
        long temp_milli = strtol(temp_str + 2, NULL, 10);
        temperature = (float)temp_milli / 1000.0;
    }

    return temperature;
}

// Function to validate temperature reading
int validate_temperature(float temperature) {
    if (temperature < -50.0 || temperature > 150.0) {
        return 0; // Invalid
    }
    return 1; // Valid
}

int main() {
    sensor_t sensors[MAX_SENSORS];
    int num_sensors;
    int i;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Discover sensors
    num_sensors = discover_sensors(sensors, MAX_SENSORS);
    if (num_sensors < 0) {
        fprintf(stderr, "Error discovering sensors. Exiting.\n");
        return 1;
    } else if (num_sensors == 0) {
        fprintf(stderr, "No DS18B20 sensors found. Exiting.\n");
        return 1;
    }

    printf("Found %d sensors.\n", num_sensors);

    // Main loop
    while (program_running) {
        for (i = 0; i < num_sensors; i++) {
            float temperature = read_temperature(sensors[i].path);

            if (temperature != ERROR_TEMP) {
                if (validate_temperature(temperature)) {
                    // Get current timestamp
                    time(&current_time);
                    time_info = localtime(&current_time);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

                    printf("%s - Sensor ID: %s, Temperature: %.2f °C\n", timestamp, sensors[i].id, temperature);
                } else {
                    fprintf(stderr, "Sensor ID: %s - Invalid temperature reading: %.2f °C\n", sensors[i].id, temperature);
                }
            } else {
                fprintf(stderr, "Sensor ID: %s - Error reading temperature.\n", sensors[i].id);
            }
        }

        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// HTU21D I2C address
#define HTU21D_ADDR 0x40

// HTU21D commands
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read temperature from HTU21D
int read_temperature(int fd, float *temperature) {
    uint8_t buf[3];
    int ret;

    // Send temperature measurement command
    ret = write(fd, &TRIGGER_TEMP_MEASURE, 1);
    if (ret != 1) {
        perror("Failed to write temperature command");
        return -1;
    }

    // Wait for measurement to complete (at least 50ms)
    usleep(50000);

    // Read 3 bytes of data
    ret = read(fd, buf, 3);
    if (ret != 3) {
        perror("Failed to read temperature data");
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    uint16_t raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = -46.85 + 175.72 * ((float)raw_temperature / 65536.0);

    return 0;
}

// Function to read humidity from HTU21D
int read_humidity(int fd, float *humidity) {
    uint8_t buf[3];
    int ret;

    // Send humidity measurement command
    ret = write(fd, &TRIGGER_HUMID_MEASURE, 1);
    if (ret != 1) {
        perror("Failed to write humidity command");
        return -1;
    }

    // Wait for measurement to complete (at least 50ms)
    usleep(50000);

    // Read 3 bytes of data
    ret = read(fd, buf, 3);
    if (ret != 3) {
        perror("Failed to read humidity data");
        return -1;
    }

    // Convert raw data to humidity (percentage)
    uint16_t raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = -6.0 + 125.0 * ((float)raw_humidity / 65536.0);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    // Main loop
    while (1) {
        // Read temperature and humidity
        if (read_temperature(i2c_fd, &temperature) == 0 &&
            read_humidity(i2c_fd, &humidity) == 0) {

            // Validate readings
            if (temperature >= -40.0 && temperature <= 125.0 &&
                humidity >= 0.0 && humidity <= 100.0) {

                // Get current time
                time(&now);
                timeinfo = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Print readings with timestamp
                printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
            } else {
                fprintf(stderr, "Invalid sensor readings: Temperature=%.2f, Humidity=%.2f\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Close I2C device (should not reach here due to signal handler)
    close(i2c_fd);
    return 0;
}

