#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// ADXL345 Registers
#define ADXL345_ADDRESS 0x53
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37

// I2C Device
#define I2C_BUS "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    uint8_t reg = DATAX0;

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for data read");
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345 (set POWER_CTL register to start measurement)
    if (write_register(i2c_fd, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to initialize ADXL345\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t x, y, z;

        // Read accelerometer data
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Get current time
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);

            // Print data with timestamp
            printf("%ld.%09ld, X: %d, Y: %d, Z: %d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        // Wait 0.1 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // This point will not be reached unless there is an error or the loop is broken.
    close(i2c_fd);
    return 0;
}

