// Define GPIO pins for DHT22 sensors
#define DHT22_PIN_1 17
#define DHT22_PIN_2 22
#define DHT22_PIN_3 23
#define DHT22_PIN_4 24

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read data from a DHT22 sensor
int read_dht22(int gpio_pin, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int i, j;

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0);
    gpioDelay(1);
    gpioWrite(gpio_pin, 1);
    gpioDelay(30);
    gpioSetMode(gpio_pin, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(gpio_pin) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for start signal (pin %d)\n", gpio_pin);
            return -1; // Timeout error
        }
    }

    // Wait for the DHT22 to pull the line high
    timeout = 0;
    while (gpioRead(gpio_pin) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 timeout waiting for end of start signal (pin %d)\n", gpio_pin);
            return -1; // Timeout error
        }
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for the line to go low
        timeout = 0;
        while (gpioRead(gpio_pin) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for data low (pin %d, bit %d)\n", gpio_pin, i);
                return -1; // Timeout error
            }
        }

        // Measure the length of the high pulse
        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio_pin) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for data high (pin %d, bit %d)\n", gpio_pin, i);
                return -1; // Timeout error
            }
        }
        long end = gpioTick();

        // Determine if it's a 0 or a 1 based on the pulse length
        if ((end - start) > 40) { // Empirical value, adjust as needed
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT22 checksum error (pin %d)\n", gpio_pin);
        return -1; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0; // Success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        float temperature, humidity;
        int result;

        // Read data from each sensor
        result = read_dht22(DHT22_PIN_1, &temperature, &humidity);
        if (result == 0) {
            printf("Sensor 1 (GPIO %d): Temperature = %.1f°C, Humidity = %.1f%%\n", DHT22_PIN_1, temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor 1 (GPIO %d)\n", DHT22_PIN_1);
        }

        result = read_dht22(DHT22_PIN_2, &temperature, &humidity);
        if (result == 0) {
            printf("Sensor 2 (GPIO %d): Temperature = %.1f°C, Humidity = %.1f%%\n", DHT22_PIN_2, temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor 2 (GPIO %d)\n", DHT22_PIN_2);
        }

        result = read_dht22(DHT22_PIN_3, &temperature, &humidity);
        if (result == 0) {
            printf("Sensor 3 (GPIO %d): Temperature = %.1f°C, Humidity = %.1f%%\n", DHT22_PIN_3, temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor 3 (GPIO %d)\n", DHT22_PIN_3);
        }

        result = read_dht22(DHT22_PIN_4, &temperature, &humidity);
        if (result == 0) {
            printf("Sensor 4 (GPIO %d): Temperature = %.1f°C, Humidity = %.1f%%\n", DHT22_PIN_4, temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor 4 (GPIO %d)\n", DHT22_PIN_4);
        }

        // Wait for 2 seconds
        sleep(2);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

