#define PWM_PIN_3 27

// Define PWM range (0-1000)
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as PWM outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM range for all pins
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Main loop to cycle through PWM values
    while (!terminate) {
        // Set PWM duty cycle to 0
        gpioPWM(PWM_PIN_1, 0);
        gpioPWM(PWM_PIN_2, 0);
        gpioPWM(PWM_PIN_3, 0);
        printf("PWM: 0, 0, 0\n");
        gpioDelay(500000); // Wait 0.5 seconds

        // Set PWM duty cycle to 500
        gpioPWM(PWM_PIN_1, 500);
        gpioPWM(PWM_PIN_2, 500);
        gpioPWM(PWM_PIN_3, 500);
        printf("PWM: 500, 500, 500\n");
        gpioDelay(500000); // Wait 0.5 seconds

        // Set PWM duty cycle to 1000
        gpioPWM(PWM_PIN_1, 1000);
        gpioPWM(PWM_PIN_2, 1000);
        gpioPWM(PWM_PIN_3, 1000);
        printf("PWM: 1000, 1000, 1000\n");
        gpioDelay(500000); // Wait 0.5 seconds
    }

    // Stop PWM outputs
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

