    // Get GPIO line for GPIO 3
    line_3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line_3) {
        perror("Error getting GPIO line for GPIO 3");
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for GPIO 2 as output
    if (gpiod_line_request_output(line_2, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line for GPIO 2 as output");
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for GPIO 3 as output
    if (gpiod_line_request_output(line_3, "gpio-control", 0) < 0) {
        perror("Error requesting GPIO line for GPIO 3 as output");
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO 2 to HIGH
    if (gpiod_line_set_value(line_2, 1) < 0) {
        perror("Error setting GPIO 2 to HIGH");
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO 2 set to HIGH\n");

    // Set GPIO 3 to LOW
    if (gpiod_line_set_value(line_3, 0) < 0) {
        perror("Error setting GPIO 3 to LOW");
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO 3 set to LOW\n");

    // Cleanup
    gpiod_line_release(line_2);
    gpiod_line_release(line_3);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the GPIO chip and line number
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 22

// Global variables for GPIO line and chip
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 0.5 seconds

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to toggle the GPIO line
    while (1) {
        // Set the GPIO line to HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO line to HIGH");
            break;
        }
        printf("GPIO %d: HIGH\n", GPIO_LINE);

        // Sleep for 0.5 seconds
        nanosleep(&sleep_time, NULL);

        // Set the GPIO line to LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO line to LOW");
            break;
        }
        printf("GPIO %d: LOW\n", GPIO_LINE);

        // Sleep for 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up resources before exiting
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define DELAY_US 20000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(GPIO_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        if (gpioPWM(GPIO_PIN, 500) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", GPIO_PIN);
            break;
        }
        printf("PWM ON\n");
        gpioDelay(DELAY_US);

        if (gpioPWM(GPIO_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", GPIO_PIN);
            break;
        }
        printf("PWM OFF\n");
        gpioDelay(DELAY_US);
    }

    gpioPWM(GPIO_PIN, 0); // Ensure PWM is off before termination
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

// Function prototypes
void set_gpio_state(int gpio, int state);
void report_gpio_state(int gpio, int state);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set GPIO states
        set_gpio_state(GPIO_17, 1);
        set_gpio_state(GPIO_22, 0);
        set_gpio_state(GPIO_23, 1);
        set_gpio_state(GPIO_24, 0);

        // Report GPIO states
        report_gpio_state(GPIO_17, 1);
        report_gpio_state(GPIO_22, 0);
        report_gpio_state(GPIO_23, 1);
        report_gpio_state(GPIO_24, 0);

        // Wait for 0.2 seconds
        time_sleep(0.2);

        // Toggle GPIO states
        set_gpio_state(GPIO_17, 0);
        set_gpio_state(GPIO_22, 1);
        set_gpio_state(GPIO_23, 0);
        set_gpio_state(GPIO_24, 1);

        // Report GPIO states
        report_gpio_state(GPIO_17, 0);
        report_gpio_state(GPIO_22, 1);
        report_gpio_state(GPIO_23, 0);
        report_gpio_state(GPIO_24, 1);

        // Wait for 0.2 seconds
        time_sleep(0.2);
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

// Function to set the state of a GPIO pin
void set_gpio_state(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to report the state of a GPIO pin
void report_gpio_state(int gpio, int state) {
    printf("GPIO %d: %s\n", gpio, state ? "HIGH" : "LOW");
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        program_running = 0;
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ENABLE_PON      (0x01)
#define TCS34725_ENABLE_AEN      (0x02)
#define TCS34725_ID              (0x12)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    uint8_t id;
    // Enable power and ALS
    uint8_t enable_reg = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    uint8_t enable_value = TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN;

    if (write(fd, &enable_reg, 1) != 1) {
        perror("Failed to write to I2C device (enable register address)");
        return -1;
    }
    if (write(fd, &enable_value, 1) != 1) {
        perror("Failed to write to I2C device (enable register value)");
        return -1;
    }

    // Verify device ID
    enable_reg = TCS34725_COMMAND_BIT | TCS34725_ID;
    if (write(fd, &enable_reg, 1) != 1) {
        perror("Failed to write to I2C device (ID register address)");
        return -1;
    }
    if (read(fd, &id, 1) != 1) {
        perror("Failed to read from I2C device (ID register)");
        return -1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02X\n", id);
        return -1;
    }

    return 0;
}

// Function to read RGBA data from the TCS34725 sensor
int tcs34725_read_rgba(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t reg;
    uint8_t data[8];

    // Read clear data
    reg = TCS34725_COMMAND_BIT | TCS34725_CDATA;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device (clear data register address)");
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device (clear data)");
        return -1;
    }
    *c = (data[1] << 8) | data[0];

    // Read red data
    reg = TCS34725_COMMAND_BIT | TCS34725_RDATA;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device (red data register address)");
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device (red data)");
        return -1;
    }
    *r = (data[1] << 8) | data[0];

    // Read green data
    reg = TCS34725_COMMAND_BIT | TCS34725_GDATA;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device (green data register address)");
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device (green data)");
        return -1;
    }
    *g = (data[1] << 8) | data[0];

    // Read blue data
    reg = TCS34725_COMMAND_BIT | TCS34725_BDATA;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device (blue data register address)");
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device (blue data)");
        return -1;
    }
    *b = (data[1] << 8) | data[0];

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // Standard I2C device on Raspberry Pi
    uint16_t r, g, b, c;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize TCS34725 sensor.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        // Read RGBA data
        if (tcs34725_read_rgba(i2c_fd, &r, &g, &b, &c) == 0) {
            // Print RGBA values
            printf("R: %5u, G: %5u, B: %5u, C: %5u\n", r, g, b, c);
        } else {
            fprintf(stderr, "Failed to read RGBA data.\n");
        }

        // Wait 0.2 seconds
        usleep(200000); // 200ms
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_21 21
#define GPIO_22 22

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_18, *line_21, *line_22;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_18) {
        gpiod_line_release(line_18);
    }
    if (line_21) {
        gpiod_line_release(line_21);
    }
    if (line_22) {
        gpiod_line_release(line_22);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    line_21 = gpiod_chip_get_line(chip, GPIO_21);
    line_22 = gpiod_chip_get_line(chip, GPIO_22);

    if (!line_18 || !line_21 || !line_22) {
        perror("Error getting GPIO line");
        goto cleanup;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_18, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line_21, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 21");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line_22, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 22");
        goto cleanup;
    }

    // Set GPIO states
    ret = gpiod_line_set_value(line_18, 1);
    if (ret < 0) {
        perror("Error setting GPIO line 18 value");
        goto cleanup;
    }
    ret = gpiod_line_set_value(line_21, 0);
    if (ret < 0) {
        perror("Error setting GPIO line 21 value");
        goto cleanup;
    }
    ret = gpiod_line_set_value(line_22, 1);
    if (ret < 0) {
        perror("Error setting GPIO line 22 value");
        goto cleanup;
    }

    // Get current time
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Print GPIO states with timestamp
    printf("[%s] GPIO %d: 1, GPIO %d: 0, GPIO %d: 1\n", ctime(&rawtime), GPIO_18, GPIO_21, GPIO_22);

    // Cleanup and exit
    gpiod_line_release(line_18);
    gpiod_line_release(line_21);
    gpiod_line_release(line_22);
    gpiod_chip_close(chip);
    return 0;

cleanup:
    // Cleanup on error
    if (line_18) {
        gpiod_line_release(line_18);
    }
    if (line_21) {
        gpiod_line_release(line_21);
    }
    if (line_22) {
        gpiod_line_release(line_22);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "image.raw"
#define MAX_CAMERA_RETRIES 3

static int camera_fd = -1;
static void *buffer = NULL;
static size_t buffer_size = 0;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int init_camera() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    camera_fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (camera_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (ioctl(camera_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(camera_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(camera_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(camera_fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;  // Set your desired width
    fmt.fmt.pix.height = 480; // Set your desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV; // Set your desired format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(camera_fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(camera_fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera_fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(camera_fd);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(camera_fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(camera_fd);
        return -1;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(camera_fd);
        return -1;
    }

    if (ioctl(camera_fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        munmap(buffer, buffer_size);
        close(camera_fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera_fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        munmap(buffer, buffer_size);
        close(camera_fd);
        return -1;
    }

    return 0;
}

int capture_image() {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(camera_fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int save_image() {
    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        return -1;
    }

    if (fwrite(buffer, 1, buffer_size, fp) != buffer_size) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int cleanup() {
    struct v4l2_buffer buf;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (camera_fd != -1) {
        if (ioctl(camera_fd, VIDIOC_STREAMOFF, &type) < 0) {
            fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        if (ioctl(camera_fd, VIDIOC_DQBUF, &buf) < 0) {
            fprintf(stderr, "Error dequeuing buffer during cleanup: %s\n", strerror(errno));
        }

        if (munmap(buffer, buffer_size) < 0) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        }

        close(camera_fd);
        camera_fd = -1;
    }

    return 0;
}

int main() {
    int retries = 0;
    int result = -1;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (retries < MAX_CAMERA_RETRIES && terminate == 0) {
        result = init_camera();
        if (result == 0) {
            break; // Camera initialized successfully
        } else {
            fprintf(stderr, "Camera initialization failed. Retry %d/%d\n", retries + 1, MAX_CAMERA_RETRIES);
            retries++;
            sleep(1); // Wait before retrying
        }
    }

    if (result != 0) {
        fprintf(stderr, "Failed to initialize camera after %d retries. Exiting.\n", MAX_CAMERA_RETRIES);
        return EXIT_FAILURE;
    }

    if (capture_image() != 0) {
        fprintf(stderr, "Image capture failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (save_image() != 0) {
        fprintf(stderr, "Failed to save image.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Image saved to %s\n", IMAGE_FILE);

    if (cleanup() != 0) {
        fprintf(stderr, "Cleanup failed.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

