#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a command to the SSD1306
int ssd1306_command(int fd, uint8_t command) {
    uint8_t buffer[2];
    buffer[0] = 0x00; // Control byte: command
    buffer[1] = command;

    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write command to SSD1306");
        return -1;
    }
    return 0;
}

// Function to write data to the SSD1306
int ssd1306_data(int fd, uint8_t data) {
    uint8_t buffer[2];
    buffer[0] = 0x40; // Control byte: data
    buffer[1] = data;

    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write data to SSD1306");
        return -1;
    }
    return 0;
}

// Function to initialize the SSD1306
int ssd1306_init(int fd) {
    // Initialization sequence (adjust based on your SSD1306 datasheet)
    ssd1306_command(fd, 0xAE); // Display off
    ssd1306_command(fd, 0xD5); // Set display clock divide ratio/oscillator frequency
    ssd1306_command(fd, 0x80); // --ratio
    ssd1306_command(fd, 0xA8); // Set multiplex ratio
    ssd1306_command(fd, SCREEN_HEIGHT - 1); // --height
    ssd1306_command(fd, 0xD3); // Set display offset
    ssd1306_command(fd, 0x00); // --offset
    ssd1306_command(fd, 0x40); // Set start line address
    ssd1306_command(fd, 0x8D); // Charge pump setting
    ssd1306_command(fd, 0x14); // --enable
    ssd1306_command(fd, 0x20); // Set memory addressing mode
    ssd1306_command(fd, 0x00); // --horizontal addressing mode
    ssd1306_command(fd, 0xA1); // Set segment re-map
    ssd1306_command(fd, 0xC8); // Set COM output scan direction
    ssd1306_command(fd, 0xDA); // Set COM pins hardware configuration
    ssd1306_command(fd, 0x12); // --alternative
    ssd1306_command(fd, 0x81); // Set contrast control
    ssd1306_command(fd, 0xCF); // --contrast
    ssd1306_command(fd, 0xD9); // Set pre-charge period
    ssd1306_command(fd, 0xF1); // --period
    ssd1306_command(fd, 0xDB); // Set VCOM deselect level
    ssd1306_command(fd, 0x40); // --level
    ssd1306_command(fd, 0xA4); // Display all points off
    ssd1306_command(fd, 0xA6); // Set normal display
    ssd1306_command(fd, 0xAF); // Display on

    return 0;
}

// Function to clear the display buffer
void ssd1306_clear_display(int fd) {
    for (int i = 0; i < (SCREEN_WIDTH * (SCREEN_HEIGHT / 8)); i++) {
        ssd1306_data(fd, 0x00);
    }
}

// Function to display a string at a specific position
void ssd1306_display_string(int fd, int x, int y, const char *str) {
    // Simple font (5x8) - replace with a proper font library for better results
    // This is a placeholder - you'll need a real font and rendering engine
