    for (int i = 0; str[i] != '\0'; i++) {
        char c = str[i];
        // Simple font representation (replace with actual font data)
        for (int j = 0; j < 5; j++) {
            // Placeholder - replace with actual font data
            uint8_t font_data = 0x00; // Assuming a simple 5x8 font
            ssd1306_data(fd, font_data);
        }
        // Add a space between characters
        ssd1306_data(fd, 0x00);
