#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 23
#define LED_PIN 24

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 10000) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Indicate timeout error
    }
    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 10000) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Indicate timeout error
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff / 2.0 / 29.1; // Speed of sound in cm/us

    return distance;
}

// Function to control the LED based on distance
void control_led(float distance) {
    if (distance < 10.0) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float distance = measure_distance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Error measuring distance\n");
        }

        gpioDelay(200); // 200 ms delay
    }

    // Cleanup and exit
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    return 0;
}

