struct gpio_pins all_gpio_pins = {{GPIO_1, GPIO_4, GPIO_5, GPIO_6, GPIO_21, GPIO_22, GPIO_23, GPIO_24}};
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[NUM_GPIOS] = {NULL};

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release all GPIO lines
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio_pin, int state) {
    int index = -1;
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (all_gpio_pins.pins[i] == gpio_pin) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        fprintf(stderr, "Error: GPIO pin %d not found in the list of pins to control.\n", gpio_pin);
        return -1;
    }

    if (!lines[index]) {
        fprintf(stderr, "Error: GPIO line for pin %d is not initialized.\n", gpio_pin);
        return -1;
    }

    int ret = gpiod_line_set_value(lines[index], state);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set value for GPIO pin %d: %s\n", gpio_pin, strerror(-ret));
        return -1;
    }

    printf("GPIO %d set to %d\n", gpio_pin, state);
    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Get the GPIO lines
    for (int i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, all_gpio_pins.pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error: Failed to get GPIO line for pin %d: %s\n", all_gpio_pins.pins[i], strerror(errno));
            // Release already acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
                lines[j] = NULL;
            }
            gpiod_chip_close(chip);
            chip = NULL;
            return 1;
        }
    }

    // Request the GPIO lines for output
    for (int i = 0; i < NUM_GPIOS; i++) {
        int ret = gpiod_line_request_output(lines[i], "gpio-control", 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to request GPIO line for pin %d for output: %s\n", all_gpio_pins.pins[i], strerror(-ret));
            // Release already acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
                lines[j] = NULL;
            }
            gpiod_chip_close(chip);
            chip = NULL;
            return 1;
        }
    }

    // Set the GPIO states
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (set_gpio_state(all_gpio_pins.pins[i], (i % 2 == 0) ? 1 : 0) != 0) {
            fprintf(stderr, "Error setting GPIO state for pin %d.\n", all_gpio_pins.pins[i]);
            // Release already acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
                lines[j] = NULL;
            }
            gpiod_chip_close(chip);
            chip = NULL;
            return 1;
        }
    }

    // Cleanup (release resources)
    for (int i = 0; i < NUM_GPIOS; i++) {
        gpiod_line_release(lines[i]);
        lines[i] = NULL;
    }
    gpiod_chip_close(chip);
    chip = NULL;

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void   *start;
    size_t  length;
};

static int fd = -1;
static struct buffer *buffers = NULL;
static unsigned int   n_buffers = 0;
static volatile sig_atomic_t stop = 0;

static void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, cleaning up...\n");
    stop = 1;
}

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

static int open_device(const char *device_name)
{
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        fprintf(stderr, "Cannot open '%s': %d, %s\n", device_name, errno, strerror(errno));
        return -1;
    }
    return fd;
}

static int init_device(int fd)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %d, %s\n", errno, strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", cap.card);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", cap.card);
        return -1;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;  /* Or whatever */
    fmt.fmt.pix.height = 480; /* Or whatever */
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV; /* Or whatever */
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %d, %s\n", errno, strerror(errno));
        return -1;
    }

    CLEAR(req);
    req.count = 4; /* Or whatever */
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %d, %s\n", errno, strerror(errno));
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        CLEAR(buf);
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %d, %s\n", errno, strerror(errno));
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL /* start anywhere */,
                                        buf.length,
                                        PROT_READ | PROT_WRITE /* required */,
                                        MAP_SHARED /* recommended */,
                                        fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            fprintf(stderr, "mmap failed: %d, %s\n", errno, strerror(errno));
            return -1;
        }
    }

    return 0;
}

static int start_capturing(int fd)
{
    unsigned int i;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        CLEAR(buf);
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF failed: %d, %s\n", errno, strerror(errno));
            return -1;
        }
    }

    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %d, %s\n", errno, strerror(errno));
        return -1;
    }

    return 0;
}

static int capture_image(int fd, void *start, size_t length)
{
    struct v4l2_buffer buf;

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %d, %s\n", errno, strerror(errno));
        return -1;
    }

    memcpy(start, buffers[buf.index].start, length);

    if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
        fprintf(stderr, "VIDIOC_QBUF failed: %d, %s\n", errno, strerror(errno));
        return -1;
    }

    return 0;
}

static int stop_capturing(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %d, %s\n", errno, strerror(errno));
        return -1;
    }

    return 0;
}

static int uninit_device(int fd)
{
    unsigned int i;

    for (i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            fprintf(stderr, "munmap failed: %d, %s\n", errno, strerror(errno));
            return -1;
        }
    }

    free(buffers);
    buffers = NULL;
    n_buffers = 0;

    return 0;
}

static int close_device(int fd)
{
    if (-1 == close(fd)) {
        fprintf(stderr, "close failed: %d, %s\n", errno, strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char **argv)
{
    const char *device_name = "/dev/video0";
    int ret = EXIT_SUCCESS;
    FILE *fp;
    char filename[64];
    time_t rawtime;
    struct tm * timeinfo;

    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    if (argc > 1) {
        device_name = argv[1];
    }

    fd = open_device(device_name);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    if (init_device(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (start_capturing(fd) == -1) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    while (!stop) {
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(filename, sizeof(filename), "image_%Y%m%d_%H%M%S.yuyv", timeinfo);

        fp = fopen(filename, "wb");
        if (!fp) {
            fprintf(stderr, "Cannot open file %s: %d, %s\n", filename, errno, strerror(errno));
            ret = EXIT_FAILURE;
            break;
        }

        if (capture_image(fd, buffers[0].start, buffers[0].length) == -1) {
            fprintf(stderr, "Capture failed\n");
            fclose(fp);
            ret = EXIT_FAILURE;
            break;
        }

        fwrite(buffers[0].start, 1, buffers[0].length, fp);
        fclose(fp);

        usleep(50000); // 0.05 seconds
    }

    if (stop_capturing(fd) == -1) {
        ret = EXIT_FAILURE;
    }

    if (uninit_device(fd) == -1) {
        ret = EXIT_FAILURE;
    }

    if (close_device(fd) == -1) {
        ret = EXIT_FAILURE;
    }

    return ret;
}

