// Initialize I2C communication
int init_i2c(const char *device) {
    if ((i2c_fd = open(device, O_RDWR)) < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Check BME280 ID
    int chip_id = read_register(BME280_REG_ID);
    if (chip_id != 0x60) {
        fprintf(stderr, "Error: Invalid chip ID: 0x%x\n", chip_id);
        close(i2c_fd);
        return -1;
    }

    // Set humidity oversampling to 1x
    if (write_register(BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_HUM register\n");
        close(i2c_fd);
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (write_register(BME280_REG_CTRL_MEAS, 0x27) < 0) { //0b00100111
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        close(i2c_fd);
        return -1;
    }

    // Set inactive duration to 0.5ms
    if (write_register(BME280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read a single byte from a BME280 register
int read_register(int reg) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, buf, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    return buf[0];
}

// Write a single byte to a BME280 register
int write_register(int reg, int value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Read calibration data from the BME280
int read_calibration_data() {
    uint8_t buffer[26];
    uint8_t buffer_h[7];

    // Read calibration data from registers 0x88 to 0xA1 (26 bytes)
    uint8_t reg = BME280_REG_CALIB_00;
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (read(i2c_fd, buffer, 26) != 26) {
        perror("Error reading calibration data");
        return -1;
    }

    // Read calibration data from registers 0xE1 to 0xE7 (7 bytes)
    reg = BME280_REG_CALIB_26;
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (read(i2c_fd, buffer_h, 7) != 7) {
        perror("Error reading humidity calibration data");
        return -1;
    }

    // Assign calibration data to struct
    calib.dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib.dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib.dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib.dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib.dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib.dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib.dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib.dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib.dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib.dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib.dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib.dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);
    calib.dig_H1 = buffer[25];
    calib.dig_H2 = (int16_t)buffer_h[0] | ((int16_t)buffer_h[1] << 8);
    calib.dig_H3 = buffer_h[2];
    calib.dig_H4 = (int16_t)((buffer_h[3] << 4) | (buffer_h[4] & 0x0F));
    calib.dig_H5 = (int16_t)((buffer_h[5] << 4) | (buffer_h[4] >> 4));
    calib.dig_H6 = (int8_t)buffer_h[6];

    return 0;
}

// Read raw temperature, pressure, and humidity data from the BME280
int read_raw_data(int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    uint8_t buffer[8];
    uint8_t reg = BME280_REG_PRESSURE_MSB;

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, buffer, 8) != 8) {
        perror("Error reading raw data");
        return -1;
