#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <signal.h>
#include <errno.h>

// Define the I2C address of the HD44780 display
#define HD44780_ADDR 0x27

// Define the I2C file descriptor
int i2c_fd;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", sig);
    // Clear the display
    lcd_clear();
    // Close the I2C device
    close(i2c_fd);
    exit(0);
}

// Function to write a command to the HD44780
void lcd_write_command(unsigned char cmd) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];
    data_u = (cmd & 0xF0);
    data_l = ((cmd << 4) & 0xF0);

    data_t[0] = data_u | 0x0C;  //en=1, rs=0
    data_t[1] = data_u | 0x08;  //en=0, rs=0
    data_t[2] = data_l | 0x0C;  //en=1, rs=0
    data_t[3] = data_l | 0x08;  //en=0, rs=0

    if (write(i2c_fd, data_t, 4) != 4) {
        perror("Failed to write command");
    }
}

// Function to write data to the HD44780
void lcd_write_data(unsigned char data) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];
    data_u = (data & 0xF0);
    data_l = ((data << 4) & 0xF0);

    data_t[0] = data_u | 0x0D;  //en=1, rs=1
    data_t[1] = data_u | 0x09;  //en=0, rs=1
    data_t[2] = data_l | 0x0D;  //en=1, rs=1
    data_t[3] = data_l | 0x09;  //en=0, rs=1

    if (write(i2c_fd, data_t, 4) != 4) {
        perror("Failed to write data");
    }
}

// Function to initialize the HD44780 display
void lcd_init() {
    // Initialization sequence
    usleep(50000); // Wait for more than 4.1ms
    lcd_write_command(0x33); // Initialize
    usleep(4500);  // Wait for more than 4.1ms
    lcd_write_command(0x32); // Initialize
    usleep(150);   // Wait for more than 150us
    lcd_write_command(0x28); // 4-bit mode, 2 lines, 5x8 font
    usleep(150);   // Wait for more than 150us
    lcd_write_command(0x0C); // Display on, cursor off, blink off
    usleep(150);   // Wait for more than 150us
    lcd_clear();   // Clear display
    usleep(150);   // Wait for more than 150us
    lcd_write_command(0x06); // Increment cursor, no shift
    usleep(150);   // Wait for more than 150us
}

// Function to clear the display
void lcd_clear() {
    lcd_write_command(0x01); // Clear display command
    usleep(2000); // Wait for more than 1.53ms
}

// Function to set the cursor position
void lcd_set_cursor(int row, int col) {
    int address;
    if (row == 0) {
        address = 0x80 + col;
    } else {
        address = 0xC0 + col;
    }
    lcd_write_command(address);
}

// Function to display a string
void lcd_display_string(const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        lcd_write_data(str[i]);
    }
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, HD44780_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the LCD
    lcd_init();

    // Main loop
    while (1) {
        // Display a string on the first line
        lcd_set_cursor(0, 0);
        lcd_display_string("Hello, LCD!");

        // Display a string on the second line
        lcd_set_cursor(1, 0);
        lcd_display_string("Raspberry Pi");

        // Wait for 10 seconds
        sleep(10);

        // Clear the display
        lcd_clear();
    }

    return 0;
}

