#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_14 14
#define GPIO_15 15

// Define validity check parameters
#define VALIDITY_CHECK_THRESHOLD 0.5
#define VALIDITY_CHECK_WINDOW 1 // seconds

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the digital value from a GPIO pin
int read_gpio(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to apply a digital value to a GPIO pin
void apply_gpio(int gpio_pin, int value) {
    int result = gpioWrite(gpio_pin, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio_pin, result);
    }
}

// Function to perform a validity check
int perform_validity_check(int gpio_pin, int value) {
    int initial_value = read_gpio(gpio_pin);
    if (initial_value < 0) return 0; // Error during initial read

    apply_gpio(gpio_pin, value);
    gpioDelay(VALIDITY_CHECK_WINDOW * 1000000); // Delay for 1 second

    int final_value = read_gpio(gpio_pin);
    if (final_value < 0) return 0; // Error during final read

    if (abs(final_value - initial_value) > VALIDITY_CHECK_THRESHOLD) {
        fprintf(stderr, "Validity check failed for GPIO %d. Initial: %d, Final: %d\n", gpio_pin, initial_value, final_value);
        return 0; // Check failed
    }

    return 1; // Check passed
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_14, PI_OUTPUT);
    gpioSetMode(GPIO_15, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Apply values to GPIO pins
        apply_gpio(GPIO_14, 1);
        apply_gpio(GPIO_15, 0);

        // Perform validity checks
        if (!perform_validity_check(GPIO_14, 1)) {
            fprintf(stderr, "Validity check failed for GPIO %d, exiting.\n", GPIO_14);
            program_running = 0;
            break;
        }
        if (!perform_validity_check(GPIO_15, 0)) {
            fprintf(stderr, "Validity check failed for GPIO %d, exiting.\n", GPIO_15);
            program_running = 0;
            break;
        }

        // Report the state
