#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "industrial/sensor_data"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_CS_PIN 8
#define SENSOR_ID "sensor1"
#define VALIDITY_CHECK_MIN 0.0
#define VALIDITY_CHECK_MAX 1023.0
#define READ_DELAY_US 1000 // 1 ms delay

// Global variables
static volatile int running = 1;
static int spi_handle;
static struct mosquitto *mosq = NULL;

// Function prototypes
float read_sensor_data();
int validate_sensor_data(float data);
char* format_json(float data);
int publish_data(const char *payload);
void signal_handler(int signum);
int init_spi();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        running = 0;
    }
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from MCP3008 via SPI
float read_sensor_data() {
    char tx_buf[3];
    char rx_buf[3];

    // MCP3008 configuration: single-ended, channel 0
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0 (10000000)
    tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1.0; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return (float)adc_value;
}

// Validate sensor data
int validate_sensor_data(float data) {
    if (data < VALIDITY_CHECK_MIN || data > VALIDITY_CHECK_MAX) {
        fprintf(stderr, "Invalid sensor data: %.2f\n", data);
        return 0; // Invalid
    }
    return 1; // Valid
}

// Format sensor data into JSON string
char* format_json(float data) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    snprintf(json_string, 100, "{\"sensor_id\": \"%s\", \"timestamp\": \"%s\", \"value\": %.2f}",
             SENSOR_ID, timestamp, data);

    return json_string;
}

// Publish data to MQTT broker
int publish_data(const char *payload) {
    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (mosq) {
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        cleanup();
        return 1;
    }

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Publishing sensor data to MQTT topic: %s\n", MQTT_TOPIC);

    // Main loop
    while (running) {
        float sensor_value = read_sensor_data();
        if (sensor_value >= 0) {
            if (validate_sensor_data(sensor_value)) {
                char *json_payload = format_json(sensor_value);
                if (json_payload != NULL) {
                    if (publish_data(json_payload) != 0) {
                        fprintf(stderr, "Failed to publish data\n");
                    }
                    free(json_payload); // Free allocated memory
                }
            }
        }
        gpioDelay(READ_DELAY_US); // Delay for 1 ms
    }

    // Cleanup and exit
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    cleanup();

    printf("Exiting.\n");
    return 0;
}

