#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 22
#define LED_PIN 27

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 400.0     // Maximum measurable distance in cm
#define MIN_DISTANCE 2.0       // Minimum measurable distance in cm
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
long measure_pulse_width();
float calculate_distance(long pulse_width);
void set_led_state(int state);
void cleanup_gpio();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the pigpio library and sets GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(LED_PIN, 0);

    return 0;
}

// Sends a 10us pulse to the HC-SR04 trigger pin
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measures the pulse width of the echo signal
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high, with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low, with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1);
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1; // Indicate timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Calculates the distance in centimeters from the pulse width
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Sets the LED state (1 for on, 0 for off)
void set_led_state(int state) {
    gpioWrite(LED_PIN, state);
}

// Cleans up the pigpio library and resets GPIO modes
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("HC-SR04 Distance Sensor Program\n");

    while (program_running) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        // Calculate the distance
        float distance = calculate_distance(pulse_width);

        // Validate the distance
        if (distance > MIN_DISTANCE && distance < MAX_DISTANCE) {
            // Set the LED state based on distance
            if (distance < 50.0) {
                set_led_state(1); // Turn on LED
            } else {
                set_led_state(0); // Turn off LED
            }

            // Print the distance
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
        }

        // Wait 0.1 seconds
        gpioDelay(100); // 100 ms
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

