// Configuration
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/temperature"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // ADC channel to read
#define TEMPERATURE_MIN 10.0
#define TEMPERATURE_MAX 40.0
#define READ_TIMEOUT_MS 100

// Global variables
static volatile int running = 1;
static int spi_handle;
static struct mosquitto *mosq = NULL;

// Function prototypes
float read_temperature();
int publish_mqtt(float temperature);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to read temperature from MCP3008 ADC
float read_temperature() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;
    int retries = 3;
    int result;

    // MCP3008 command to read a single channel
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | MCP3008_CHANNEL) << 4; // Single-ended mode, channel selection
    spi_tx_buf[2] = 0x00; // Don't care

    while (retries > 0) {
        result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 0) {
            // Extract ADC value from the response
            adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

            // Convert ADC value to temperature (example linear conversion)
            // Assuming 3.3V reference and 10-bit ADC
            float temperature = (adc_value * 3.3 / 1024.0) * 100.0; // Example: 0-100°C
            return temperature;
        } else {
            fprintf(stderr, "SPI read failed (attempt %d): %d\n", 4 - retries, result);
            retries--;
            gpioDelay(READ_TIMEOUT_MS * 1000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1.0; // Indicate error
}

// Function to publish temperature reading to MQTT broker
int publish_mqtt(float temperature) {
    char payload[50];
    int ret;

    // Format the payload
    snprintf(payload, sizeof(payload), "%.2f", temperature);

    // Publish the message
    ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

int main() {
    int rc;
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create mosquitto instance\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read temperature
        temperature = read_temperature();

        // Validate temperature reading
        if (temperature >= TEMPERATURE_MIN && temperature <= TEMPERATURE_MAX) {
            // Publish to MQTT
            if (publish_mqtt(temperature) != 0) {
                fprintf(stderr, "Failed to publish temperature.\n");
            }
        } else {
            fprintf(stderr, "Temperature reading out of range: %.2f\n", temperature);
        }

        // Wait for a short period
        sleep(5);
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    spiClose(spi_handle);
    gpioTerminate();
    mosquitto_lib_cleanup();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
