#include <math.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_HOST "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "industrial/sensor_data"
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_FULL_SCALE_VOLTAGE 4.096 // +/- 4.096V
#define ADS1115_SAMPLE_RATE 128          // Hz
#define ADS1115_PGA 1                   // +/- 1.6V range
#define NUM_READINGS 10

// Global variables
static int i2c_handle;
static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function prototypes
int init_i2c();
int init_mqtt();
int read_ads1115(float *voltage);
int publish_data(float voltage);
void signal_handler(int signum);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize MQTT client
int init_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating Mosquitto instance\n");
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error starting MQTT loop: %s\n", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// Read data from ADS1115
int read_ads1115(float *voltage) {
    unsigned char config[3];
    unsigned char buf[2];
    int16_t raw_value;

    // Configure ADS1115 for single-ended input A0, 128 SPS, +/-1.6V
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0x40 | (ADS1115_PGA << 1) | 0x04; // Single-shot mode, PGA/gain, 128 SPS
    config[2] = 0x83; // Disable comparator, non-latching, alert/ready active low

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    buf[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    raw_value = (buf[0] << 8) | buf[1];

    // Convert raw value to voltage
    *voltage = (float)raw_value * ADS1115_FULL_SCALE_VOLTAGE / 32768.0;

    return 0;
}

// Publish data to MQTT broker
int publish_data(float voltage) {
    char payload[50];
    int rc;

    snprintf(payload, sizeof(payload), "{\"voltage\": %.3f}", voltage);

    rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(rc));
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioTerminate();
}

int main() {
    float voltage;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    for (i = 0; i < NUM_READINGS && running; i++) {
        if (read_ads1115(&voltage) == 0) {
            printf("Voltage: %.3f V\n", voltage);
            if (publish_data(voltage) != 0) {
                fprintf(stderr, "Failed to publish data\n");
            }
        } else {
            fprintf(stderr, "Failed to read ADS1115 data\n");
        }
        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

