        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for GPIO 23 as output
    ret = gpiod_line_request_output(line_23, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for GPIO 23 as output");
        gpiod_line_release(line_17);
        gpiod_line_release(line_23);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO 17 to HIGH
    ret = gpiod_line_set_value(line_17, 1);
    if (ret < 0) {
        perror("Error setting GPIO 17 to HIGH");
        gpiod_line_release(line_17);
        gpiod_line_release(line_23);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO 17 set to HIGH\n");

    // Set GPIO 23 to LOW
    ret = gpiod_line_set_value(line_23, 0);
    if (ret < 0) {
        perror("Error setting GPIO 23 to LOW");
        gpiod_line_release(line_17);
        gpiod_line_release(line_23);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO 23 set to LOW\n");

    // Cleanup (release lines and close chip)
    gpiod_line_release(line_17);
    gpiod_line_release(line_23);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
