#include <pigpio.h>

#define GPIO_PIN 22

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    int state = 0;
