// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Calibration data
uint16_t dig_T1;
int16_t dig_T2;
int16_t dig_T3;
uint16_t dig_P1;
int16_t dig_P2;
int16_t dig_P3;
int16_t dig_P4;
int16_t dig_P5;
int16_t dig_P6;
int16_t dig_P7;
int16_t dig_P8;
int16_t dig_P9;

// Function prototypes
int i2c_setup(const char *device);
int bmp280_read_calibration_data();
int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature);
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine);
void signal_handler(int signal);

// Signal handler for graceful exit
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// I2C setup function
int i2c_setup(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read calibration data from BMP280
int bmp280_read_calibration_data() {
    uint8_t buffer[26];
    if (read(i2c_fd, buffer, 26) != 26) {
        perror("Error reading calibration data");
        return -1;
    }

    dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data from BMP280
int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure) {
    uint8_t buffer[6];
    uint8_t write_buffer[2];

    // Set the BMP280 to forced mode
    write_buffer[0] = BMP280_REG_CTRL_MEAS;
    write_buffer[1] = 0b00110011; // Temperature oversampling x1, Pressure oversampling x1, Forced mode
    if (write(i2c_fd, write_buffer, 2) != 2) {
        perror("Error writing to BMP280");
        return -1;
    }

    usleep(10000); // Wait for measurement to complete (adjust as needed)

    write_buffer[0] = BMP280_REG_PRESS_MSB;
    if (write(i2c_fd, write_buffer, 1) != 1) {
        perror("Error writing to BMP280");
        return -1;
    }

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading raw data");
        return -1;
    }

    *pressure = ((int32_t)buffer[0] << 12) | ((int32_t)buffer[1] << 4) | ((int32_t)buffer[2] >> 4);
    *temperature = ((int32_t)buffer[3] << 12) | ((int32_t)buffer[4] << 4) | ((int32_t)buffer[5] >> 4);

    return 0;
}

// Function to compensate temperature
double bmp280_compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double t_fine;

    var1 = (((double)raw_temperature) / 16384.0 - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Function to compensate pressure
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)dig_P4) * 65536.0);
    var1 = (((double)dig_P3) * var1 * var1 / 524288.0 + ((double)dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)dig_P7)) / 16.0;

    return p;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup("/dev/i2c-1");
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Read calibration data
    if (bmp280_read_calibration_data() < 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;

    // Main loop
    while (program_running) {
        // Read raw data
        if (bmp280_read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = bmp280_compensate_temperature(raw_temperature);
            pressure = bmp280_compensate_pressure(raw_pressure, temperature);

            // Print results
            printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read raw data. Retrying.\n");
        }

        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define the GPIO pin for PWM output
#define PWM_PIN 4

// Define the PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define the PWM range (resolution)
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pin as an output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set the PWM frequency
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);

    // Set the PWM range
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Main loop to continuously set the PWM duty cycle
    while (!terminate)
    {
        // Set the PWM duty cycle to 50% (half of the range)
        gpioPWM(PWM_PIN, PWM_RANGE / 2);

        // Print the state to standard output
        printf("PWM duty cycle set to 50%% (half of the range)\n");

        // Wait for a short period (e.g., 1 second)
        gpioDelay(1000000); // 1 second delay
    }

    // Stop the PWM output
    gpioPWM(PWM_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    // Exit the program
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_5, *line_6, *line_13;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_5) {
        gpiod_line_release(line_5);
    }
    if (line_6) {
        gpiod_line_release(line_6);
    }
    if (line_13) {
        gpiod_line_release(line_13);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_5 = gpiod_chip_get_line(chip, GPIO_5);
    line_6 = gpiod_chip_get_line(chip, GPIO_6);
    line_13 = gpiod_chip_get_line(chip, GPIO_13);

    if (!line_5 || !line_6 || !line_13) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_5, "app", 0) < 0 ||
        gpiod_line_request_output(line_6, "app", 0) < 0 ||
        gpiod_line_request_output(line_13, "app", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line_5);
        gpiod_line_release(line_6);
        gpiod_line_release(line_13);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO states
    gpiod_line_set_value(line_5, 1);
    gpiod_line_set_value(line_6, 0);
    gpiod_line_set_value(line_13, 1);

    // Get current time
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Print GPIO states with timestamp
    printf("[%s] GPIO %d: 1, GPIO %d: 0, GPIO %d: 1\n", ctime(&rawtime), GPIO_5, GPIO_6, GPIO_13);

    // Release GPIO lines
    gpiod_line_release(line_5);
    gpiod_line_release(line_6);
    gpiod_line_release(line_13);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

