    while (running) {
        // Read sensor data
        int temperature = read_sensor_data();

        // Format data as JSON
        char payload[50];
        snprintf(payload, sizeof(payload), "{\"sensor_id\": \"%s\", \"temperature\": %d}", SENSOR_ID, temperature);

        // Publish data
        if (publish_data(MQTT_TOPIC, payload) != 0) {
            fprintf(stderr, "Error publishing data. Retrying in 5 seconds.\n");
            sleep(5);
            continue; // Retry publishing
        }

        printf("Published: %s\n", payload);

        // Wait for a short period
        sleep(5);
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

