// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stdout, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

int main() {
    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 2 as an output
    gpioSetMode(GPIO_2, PI_OUTPUT);

    // Set GPIO 3 as an output
    gpioSetMode(GPIO_3, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Set GPIO 2 HIGH
        gpioWrite(GPIO_2, 1);
        fprintf(stdout, "GPIO 2: HIGH\n");
        fflush(stdout); // Ensure output is immediately written
        usleep(500000); // Wait for 0.5 seconds

        // Set GPIO 2 LOW
        gpioWrite(GPIO_2, 0);
        fprintf(stdout, "GPIO 2: LOW\n");
        fflush(stdout); // Ensure output is immediately written
        usleep(500000); // Wait for 0.5 seconds

        // Set GPIO 3 HIGH
        gpioWrite(GPIO_3, 1);
        fprintf(stdout, "GPIO 3: HIGH\n");
        fflush(stdout); // Ensure output is immediately written
        usleep(500000); // Wait for 0.5 seconds

        // Set GPIO 3 LOW
        gpioWrite(GPIO_3, 0);
        fprintf(stdout, "GPIO 3: LOW\n");
        fflush(stdout); // Ensure output is immediately written
        usleep(500000); // Wait for 0.5 seconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_27 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_17, *line_27;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_27) {
        gpiod_line_release(line_27);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for GPIO 17
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line_17) {
        perror("Error getting GPIO line for GPIO 17");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for GPIO 27
    line_27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line_27) {
        perror("Error getting GPIO line for GPIO 27");
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for GPIO 17 as output
    ret = gpiod_line_request_output(line_17, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for GPIO 17 as output");
        gpiod_line_release(line_17);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for GPIO 27 as output
    ret = gpiod_line_request_output(line_27, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for GPIO 27 as output");
        gpiod_line_release(line_17);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Get current time
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        // Set GPIO 17 to HIGH
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 to HIGH");
            break;
        }
        printf("%s: GPIO 17 set to HIGH\n", buf);

        // Set GPIO 27 to LOW
        ret = gpiod_line_set_value(line_27, 0);
        if (ret < 0) {
            perror("Error setting GPIO 27 to LOW");
            break;
        }
        printf("%s: GPIO 27 set to LOW\n", buf);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup (should not reach here under normal circumstances due to the signal handler)
    gpiod_line_release(line_17);
    gpiod_line_release(line_27);
    gpiod_chip_close(chip);

    return 1;
}

