        gpioWrite(GPIO_19, 0);
        printf("GPIO 18: HIGH, GPIO 19: LOW\n");

        // Wait for 0.5 seconds
        time_sleep(0.5);

        // Set GPIO 18 LOW, GPIO 19 HIGH
        gpioWrite(GPIO_18, 0);
        gpioWrite(GPIO_19, 1);
        printf("GPIO 18: LOW, GPIO 19: HIGH\n");

        // Wait for 0.5 seconds
        time_sleep(0.5);
    }

    // Clean up and exit
    gpioWrite(GPIO_18, 0); // Ensure GPIO is LOW before exiting
    gpioWrite(GPIO_19, 0);
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define the UART port (ttyAMA0 or ttyS0)
#define UART_PORT "/dev/ttyS0"

// Define the baud rate
#define BAUD_RATE B115200

// Global variable for the UART file descriptor
int uart_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (uart_fd != -1) {
        close(uart_fd);
        printf("UART port closed.\n");
    }
    exit(0);
}

// Function to initialize the UART port
int init_uart(const char *port) {
    struct termios tty;

    // Open the UART port
    uart_fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd < 0) {
        perror("Error opening UART port");
        return -1;
    }

    // Get the current attributes of the UART port
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting UART attributes");
        close(uart_fd);
        return -1;
    }

    // Configure the UART port
    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 115200 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read at least 0 characters
    tty.c_cc[VTIME] = 5;                             // Wait for 0.5 seconds

    // Set the attributes of the UART port
    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting UART attributes");
        close(uart_fd);
        return -1;
    }

    printf("UART port %s initialized successfully.\n", port);
    return 0;
}

// Function to read data from the UART port
int read_uart(int fd, char *buffer, int max_len) {
    ssize_t bytes_read = read(fd, buffer, max_len - 1);
    if (bytes_read < 0) {
        perror("Error reading from UART port");
        return -1;
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return bytes_read;
    }
}

// Function to process the received data
void process_data(const char *data) {
    // Placeholder for data processing logic
    printf("Received data: %s\n", data);
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the UART port
    if (init_uart(UART_PORT) != 0) {
        fprintf(stderr, "UART initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    char buffer[256];
    while (1) {
        // Read data from the UART port
        int bytes_read = read_uart(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            // Process the received data
            process_data(buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Retrying...\n");
            sleep(1); // Wait before retrying
        }
        usleep(100000); // Sleep for 100ms to avoid busy-waiting
    }

    return 0;
}

