// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as an output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency to 1000 Hz
    gpioSetPWMfrequency(PWM_PIN, 1000);

    // Set PWM range (resolution)
    gpioSetPWMrange(PWM_PIN, 100);

    // Main loop to control PWM duty cycle
    for (int duty_cycle = 0; duty_cycle <= 100 && !terminate; ++duty_cycle) {
        // Set the PWM duty cycle
        gpioPWM(PWM_PIN, duty_cycle);

        // Print the current duty cycle to standard output
        printf("PWM Duty Cycle: %d\n", duty_cycle);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Reset PWM to 0 after the loop
    gpioPWM(PWM_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

