#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define the GPIO pin number (BCM numbering)
#define GPIO_PIN 4

// Define the number of GPIO lines
#define NUM_LINES 1

// Define the number of retries for DHT22 communication
#define DHT22_RETRIES 3

// Define the timeout for DHT22 communication (in milliseconds)
#define DHT22_TIMEOUT 1000

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

// Structure to hold DHT22 data
typedef struct {
    uint16_t humidity;
    uint16_t temperature;
} DHT22Data;

// Signal handler for graceful shutdown
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO line
int init_gpio(int pin)
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "dht22_reader";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read data from the DHT22 sensor
int read_dht22(DHT22Data *data)
{
    int retries = DHT22_RETRIES;
    int i, j;
    uint8_t raw_data[5] = {0};

    while (retries > 0) {
        // Send start signal
        if (gpiod_line_set_direction(line, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
            perror("Error setting GPIO direction to output");
            return -1;
        }
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Error setting GPIO value to 0");
            return -1;
        }
        usleep(1000); // 1 ms
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Error setting GPIO value to 1");
            return -1;
        }
        usleep(30); // 30 us

        // Switch to input and wait for response
        if (gpiod_line_set_direction(line, GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
            perror("Error setting GPIO direction to input");
            return -1;
        }
        usleep(40); // 40 us

        // Read 40 bits (5 bytes)
        for (i = 0; i < 5; i++) {
            // Wait for low
            struct timespec start, now;
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(line) == 0) {
                clock_gettime(CLOCK_MONOTONIC, &now);
                if ((now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000 > DHT22_TIMEOUT) {
                    fprintf(stderr, "Timeout waiting for low signal\n");
                    goto retry;
                }
            }

            // Wait for high
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(line) == 1) {
                clock_gettime(CLOCK_MONOTONIC, &now);
                if ((now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000 > DHT22_TIMEOUT) {
                    fprintf(stderr, "Timeout waiting for high signal\n");
                    goto retry;
                }
            }

            // Measure bit duration
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(line) == 0) {
                clock_gettime(CLOCK_MONOTONIC, &now);
                if ((now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000 > DHT22_TIMEOUT) {
                    fprintf(stderr, "Timeout waiting for end of bit\n");
                    goto retry;
                }
            }
            long duration = (now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000;

            // Determine bit value
            if (duration > 40) {
                raw_data[i] |= (1 << (7 - (i % 8)));
            }
        }

        // Validate checksum
        if (raw_data[4] == ((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) & 0xFF)) {
            // Convert data
            data->humidity = ((uint16_t)raw_data[0] << 8) | raw_data[1];
            data->temperature = ((uint16_t)raw_data[2] << 8) | raw_data[3];

            // Check for negative temperature
            if (data->temperature & 0x8000) {
                data->temperature &= 0x7FFF; // Clear sign bit
                data->temperature = -data->temperature;
            }

            return 0; // Success
        } else {
            fprintf(stderr, "Checksum error\n");
        }

    retry:
        retries--;
        usleep(100000); // Wait 100 ms before retrying
    }

    return -1; // Failure
}

// Function to close the GPIO line
void close_gpio()
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    DHT22Data data;
    int ret;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return EXIT_FAILURE;
    }

    // Read DHT22 data
    ret = read_dht22(&data);
    if (ret == 0) {
        // Print data to standard output
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", (float)data.temperature / 10.0, (float)data.humidity / 10.0);
    } else {
        fprintf(stderr, "Failed to read DHT22 data\n");
    }

    // Close GPIO
    close_gpio();

    return ret == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

