        // Set GPIO states to LOW
        set_gpio_state(GPIO_17, 0);
        set_gpio_state(GPIO_23, 0);
        set_gpio_state(GPIO_24, 0);
        set_gpio_state(GPIO_25, 0);

        // Report GPIO states
        report_gpio_state(GPIO_17, 0);
        report_gpio_state(GPIO_23, 0);
        report_gpio_state(GPIO_24, 0);
        report_gpio_state(GPIO_25, 0);

        // Wait for 10 seconds
        sleep(10);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

// Function to initialize pigpio and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);
    gpioSetMode(GPIO_25, PI_OUTPUT);

    return 0;
}

// Function to set the state of a GPIO pin
void set_gpio_state(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to report the state of a GPIO pin
void report_gpio_state(int gpio, int state) {
    printf("GPIO %d: %s\n", gpio, state ? "HIGH" : "LOW");
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
    printf("GPIO resources released. Exiting.\n");
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT. Cleaning up and exiting.\n");
        program_running = 0;
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // ADC channel to read
#define MQTT_HOST "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/sensor/mcp3008"
#define MQTT_CLIENT_ID "rpi_mcp3008_publisher"
#define READ_INTERVAL_SEC 5

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int publish_mqtt(int adc_value);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, terminating...\n", signum);
        terminate = 1;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    // Transfer SPI data
    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to publish MQTT message
int publish_mqtt(int adc_value) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", adc_value);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT publish failed: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: MQTT initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT connect failed: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            // Publish MQTT message
            if (publish_mqtt(adc_value) != 0) {
                fprintf(stderr, "Error: Failed to publish MQTT message\n");
            }
        }

        // Wait for the next interval
        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    spiClose(spi_handle);
    gpioTerminate();
    mosquitto_lib_cleanup();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_PATH "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FILE "camera_capture.jpg"

struct buffer {
    void   *start;
    size_t  length;
};

int main() {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct buffer *buffers = NULL;
    unsigned int n_buffers = 0;
    enum v4l2_buf_type type;
    unsigned int i;
    FILE *fp;
    int ret;

    fd = open(DEVICE_PATH, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Request only one buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return EXIT_FAILURE;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            free(buffers);
            return EXIT_FAILURE;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            free(buffers);
            return EXIT_FAILURE;
        }
    }

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(fd);
            for (unsigned int j = 0; j < n_buffers; ++j) {
                munmap(buffers[j].start, buffers[j].length);
            }
            free(buffers);
            return EXIT_FAILURE;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    ret = fwrite(buffers[buf.index].start, 1, buf.bytesused, fp);
    if (ret != buf.bytesused) {
        perror("Error writing to file");
        fclose(fp);
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            munmap(buffers[j].start, buffers[j].length);
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    fclose(fp);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer after capture");
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
    }

    for (i = 0; i < n_buffers; ++i) {
        munmap(buffers[i].start, buffers[i].length);
    }

    free(buffers);
    close(fd);

    printf("Image saved to %s\n", IMAGE_FILE);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM outputs
#define PWM_PIN_1 4
#define PWM_PIN_2 5
#define PWM_PIN_3 6
#define PWM_PIN_4 7
#define PWM_PIN_5 8
#define PWM_PIN_6 9

// Define PWM range (0-1000)
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main()
{
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as PWM outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);
    gpioSetMode(PWM_PIN_6, PI_OUTPUT);

    // Set PWM range for all pins
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_5, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_6, PWM_RANGE);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN_1, 1000); // 1 kHz
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);
    gpioSetPWMfrequency(PWM_PIN_4, 1000);
    gpioSetPWMfrequency(PWM_PIN_5, 1000);
    gpioSetPWMfrequency(PWM_PIN_6, 1000);

    // Main loop to set PWM values and report them
    while (!terminate)
    {
        // Set PWM duty cycle for each pin (example values)
        gpioPWM(PWM_PIN_1, 250);
        gpioPWM(PWM_PIN_2, 500);
        gpioPWM(PWM_PIN_3, 750);
        gpioPWM(PWM_PIN_4, 100);
        gpioPWM(PWM_PIN_5, 300);
        gpioPWM(PWM_PIN_6, 600);

        // Print PWM values to standard output
        printf("PWM_PIN_1: %d, PWM_PIN_2: %d, PWM_PIN_3: %d, PWM_PIN_4: %d, PWM_PIN_5: %d, PWM_PIN_6: %d\n",
               gpioGetPWMdutycycle(PWM_PIN_1),
               gpioGetPWMdutycycle(PWM_PIN_2),
               gpioGetPWMdutycycle(PWM_PIN_3),
               gpioGetPWMdutycycle(PWM_PIN_4),
               gpioGetPWMdutycycle(PWM_PIN_5),
               gpioGetPWMdutycycle(PWM_PIN_6));

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM outputs
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioPWM(PWM_PIN_5, 0);
    gpioPWM(PWM_PIN_6, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define number of cycles
#define NUM_CYCLES 3

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_17, *line_18;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_18) {
        gpiod_line_release(line_18);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int i;
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100ms

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line 17
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line_17) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line 18
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line_18) {
        perror("Error getting GPIO line 18");
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 17 as output
    ret = gpiod_line_request_output(line_17, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 as output");
        gpiod_line_release(line_18);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line 18 as output
    ret = gpiod_line_request_output(line_18, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18 as output");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO 17 high, GPIO 18 low
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 high");
            break;
        }
        ret = gpiod_line_set_value(line_18, 0);
        if (ret < 0) {
            perror("Error setting GPIO 18 low");
            break;
        }
        printf("Cycle %d: GPIO 17=1, GPIO 18=0\n", i + 1);
        nanosleep(&sleep_time, NULL);

        // Set GPIO 17 low, GPIO 18 high
        ret = gpiod_line_set_value(line_17, 0);
        if (ret < 0) {
            perror("Error setting GPIO 17 low");
            break;
        }
        ret = gpiod_line_set_value(line_18, 1);
        if (ret < 0) {
            perror("Error setting GPIO 18 high");
            break;
        }
        printf("Cycle %d: GPIO 17=0, GPIO 18=1\n", i + 1);
        nanosleep(&sleep_time, NULL);

        // Set GPIO 17 high, GPIO 18 high
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 high");
            break;
        }
        ret = gpiod_line_set_value(line_18, 1);
        if (ret < 0) {
            perror("Error setting GPIO 18 high");
            break;
        }
        printf("Cycle %d: GPIO 17=1, GPIO 18=1\n", i + 1);
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define the GPIO chip and line number
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

// Global variables for GPIO line and chip
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 5;  // 5 seconds
    sleep_time.tv_nsec = 0; // 0 nanoseconds

    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the GPIO line for output
    ret = gpiod_line_request_output(line, "rpi-gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop to toggle the GPIO line
    while (1) {
        // Set the GPIO line to HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO line to HIGH");
            break;
        }
        printf("GPIO %d: HIGH\n", GPIO_LINE);

        // Sleep for 5 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break;
        }

        // Set the GPIO line to LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO line to LOW");
            break;
        }
        printf("GPIO %d: LOW\n", GPIO_LINE);

        // Sleep for 5 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break;
        }
    }

    // Release the GPIO line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x48

// Define the display values
const unsigned char display_values[] = {0xC0, 0xF9, 0xA4, 0xB0, 0x99, 0x92, 0x82, 0xF8, 0x80, 0x90};

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a value to the PCF8574
int write_pcf8574(int fd, unsigned char value) {
    if (write(fd, &value, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int main() {
    // Register the signal handler
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Iterate through the display values
        for (size_t i = 0; i < sizeof(display_values) / sizeof(display_values[0]); ++i) {
            // Write the value to the PCF8574
            if (write_pcf8574(i2c_fd, display_values[i]) != 0) {
                // Error writing, exit the loop
                break;
            }

            // Wait for 0.5 seconds
            usleep(500000);
        }
    }

    // This point should not be reached due to the signal handler
    close(i2c_fd);
    return 0;
}

