#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define timeout duration (in microseconds)
#define TIMEOUT 50000 // 50ms

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the HC-SR04 sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin high
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin low
}

// Function to measure the echo pulse duration
long measure_pulse_duration() {
    long start_time = 0, end_time = 0;

    // Wait for the echo pin to go high (start of the pulse)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Timeout waiting for echo start.\n");
        return -1; // Indicate timeout error
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low (end of the pulse)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Timeout waiting for echo end.\n");
        return -1; // Indicate timeout error
    }

    end_time = gpioTick();

    return end_time - start_time; // Return the pulse duration in microseconds
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_duration) {
    return (pulse_duration * 0.0343) / 2.0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    fprintf(stdout, "HC-SR04 sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse duration
        long pulse_duration = measure_pulse_duration();

        if (pulse_duration > 0) {
            // Calculate the distance
            float distance = calculate_distance(pulse_duration);

            // Print the distance to standard output
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Could not measure pulse duration.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Terminate the pigpio library
    gpioTerminate();

    fprintf(stdout, "Program terminated.\n");
    return 0;
}

