    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    int ret;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Cannot open device");
        return -1;
    }

    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
        if (ret < 0) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("mmap");
            close(fd);
            return -1;
        }
    }

    return 0;
}

int start_capturing()
{
    unsigned int i;
    int type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    int ret;

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret < 0) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    ret = ioctl(fd, VIDIOC_STREAMON, &type);
    if (ret < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    return 0;
}

int capture_image(void **image_data, size_t *image_size)
{
    struct v4l2_buffer buf;
    int ret;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_DQBUF, &buf);
    if (ret < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *image_data = buffers[buf.index].start;
    *image_size = buffers[buf.index].length;

    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    return 0;
}

int stop_capturing()
{
    int type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    int ret;

    ret = ioctl(fd, VIDIOC_STREAMOFF, &type);
    if (ret < 0) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }

    return 0;
}

int uninit_device()
{
    unsigned int i;
    int ret;

    for (i = 0; i < n_buffers; ++i) {
        ret = munmap(buffers[i].start, buffers[i].length);
        if (ret < 0) {
            perror("munmap");
            return -1;
        }
    }

    free(buffers);

    ret = close(fd);
    if (ret < 0) {
        perror("close");
        return -1;
    }

    return 0;
}

int save_image(const void *image_data, size_t image_size, const char *filename)
{
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    size_t bytes_written = fwrite(image_data, 1, image_size, fp);
    if (bytes_written != image_size) {
        fprintf(stderr, "Error writing to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main()
{
    void *image_data;
    size_t image_size;
    time_t rawtime;
    struct tm * timeinfo;
    char filename[80];
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_device() < 0) {
        fprintf(stderr, "Failed to initialize device\n");
        return EXIT_FAILURE;
    }

    if (start_capturing() < 0) {
        fprintf(stderr, "Failed to start capturing\n");
        uninit_device();
        return EXIT_FAILURE;
    }

    while (!stop) {
        if (capture_image(&image_data, &image_size) < 0) {
            fprintf(stderr, "Failed to capture image\n");
            break;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(filename, sizeof(filename), "image_%Y%m%d_%H%M%S.yuyv", timeinfo);

        if (save_image(image_data, image_size, filename) < 0) {
            fprintf(stderr, "Failed to save image\n");
        }

        usleep(100000); // 0.1 seconds
    }

    if (stop_capturing() < 0) {
        fprintf(stderr, "Failed to stop capturing\n");
    }

    if (uninit_device() < 0) {
        fprintf(stderr, "Failed to uninitialize device\n");
    }

    return EXIT_SUCCESS;
}

