    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to display a number on the PCF8574
void display_number(int fd, int number) {
    // Map the number to a byte to be sent to the PCF8574
    // This is a placeholder; you'll need to replace it with
    // the actual mapping for your specific display.
    // For example, if you're using a 7-segment display,
    // you'd need to define the segments for each digit.
    unsigned char digit_patterns[] = {
        0x3F, // 0
        0x06, // 1
        0x5B, // 2
        0x4F, // 3
        0x66, // 4
        0x6D, // 5
        0x7D, // 6
        0x07, // 7
        0x7F, // 8
        0x6F  // 9
    };

    if (number < 0 || number > 9) {
        fprintf(stderr, "Invalid number: %d\n", number);
        return;
    }

    unsigned char byte_to_send = digit_patterns[number];

    // Send the byte to the PCF8574
    if (write(fd, &byte_to_send, 1) != 1) {
        perror("Error writing to I2C device");
    }
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(PCF8574_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Display numbers 0-9 on the PCF8574
    for (int i = 0; i < 10; i++) {
        display_number(i2c_fd, i);
        usleep(100000); // Delay for 100ms
    }

    // Clean up and exit
    close(i2c_fd);
    return 0;
}

