    // Set GPIO modes
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetMode(INPUT_PIN, PI_INPUT);
    gpioSetMode(OUTPUT_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read input value from GPIO 23
        input_value = gpioRead(INPUT_PIN);

        // Set GPIO 24 to the same value
        gpioWrite(OUTPUT_PIN, input_value);

        // Calculate duty cycle based on input value
        duty_cycle = (input_value == 1) ? 255 : 0;

        // Set PWM duty cycle on GPIO 18
        gpioPWM(PWM_PIN, duty_cycle);

        // Report state to standard output
        printf("Input: %d, Output: %d, PWM: %d\n", input_value, input_value, duty_cycle);

