int get_gpio_input(struct gpiod_line *line);
int check_validity(int input);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Release GPIO lines
    if (line_2) {
        gpiod_line_release(line_2);
    }
    if (line_3) {
        gpiod_line_release(line_3);
    }
    if (line_17) {
