    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Initialize GPIO pin
int gpio_init(int gpio, struct gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        perror("Error getting GPIO line");
        return -1;
    }

    if (gpiod_line_request_output(*line, "app", 0) < 0) {
        perror("Error requesting GPIO line as output");
        return -1;
    }

    return 0;
}

// Set GPIO output value
int set_gpio_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO output value");
        return -1;
    }
    return 0;
}

// Get GPIO input value
int get_gpio_input(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO input value");
        return -1;
    }
    return value;
}

// Check validity of input
int check_validity(int input) {
    return (input == 1) ? 1 : 0;
}

