#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

// SHT31 I2C address
#define SHT31_ADDR 0x44

// Measurement command (High Repeatability, Clock Stretching disabled)
#define MEASURE_CMD 0x2C06

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHT31
int read_sht31(int fd, float *temperature, float *humidity) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[6];

    // Send measurement command
    if (write(fd, cmd, 2) != 2) {
        perror("Failed to write measurement command");
        return -1;
    }

    // Wait for measurement (at least 10 ms)
    usleep(20000); // 20 ms

    // Read 6 bytes of data
    if (read(fd, data, 6) != 6) {
        perror("Failed to read data");
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data to temperature and humidity
    int temp_raw = (data[0] << 8) | data[1];
    int hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity;

    while (1) {
        if (read_sht31(i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read SHT31 data\n");
        }

        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define the GPIO pins to be controlled
#define GPIO_5   5
#define GPIO_6   6
#define GPIO_12  12
#define GPIO_16  16
#define GPIO_19  19
#define GPIO_20  20
#define GPIO_23  23
#define GPIO_24  24
#define GPIO_25  25
#define GPIO_26  26

// Array of GPIO pins
int gpio_pins[] = {GPIO_5, GPIO_6, GPIO_12, GPIO_16, GPIO_19, GPIO_20, GPIO_23, GPIO_24, GPIO_25, GPIO_26};

// Number of GPIO pins
#define NUM_GPIO_PINS (sizeof(gpio_pins) / sizeof(gpio_pins[0]))

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio, int state)
{
    int result = gpioWrite(gpio, state);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d to state %d: %d\n", gpio, state, result);
        return -1;
    }
    return 0;
}

// Function to report the state of a GPIO pin
void report_gpio_state(int gpio, int state)
{
    printf("GPIO %d: %s\n", gpio, (state == 1) ? "HIGH" : "LOW");
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    for (int i = 0; i < NUM_GPIO_PINS; i++) {
        if (gpioSetMode(gpio_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to toggle the GPIO pins
    while (program_running) {
        for (int i = 0; i < NUM_GPIO_PINS; i++) {
            // Toggle the state of the GPIO pin
            int current_state = gpioRead(gpio_pins[i]);
            int new_state = (current_state == 0) ? 1 : 0;

            if (set_gpio_state(gpio_pins[i], new_state) == 0) {
                report_gpio_state(gpio_pins[i], new_state);
            } else {
                program_running = 0; // Exit on error
                break;
            }

            // Small delay to prevent excessive CPU usage
            usleep(100000); // 100ms
        }
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0;
}

