#define GPIO_22 22
#define GPIO_27 27

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stdout, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Set GPIO pins HIGH
        gpioWrite(GPIO_17, 1);
        gpioWrite(GPIO_22, 1);
        gpioWrite(GPIO_27, 1);

        // Report state to standard output
        fprintf(stdout, "GPIO %d: HIGH, GPIO %d: HIGH, GPIO %d: HIGH\n", GPIO_17, GPIO_22, GPIO_27);

        // Wait for 1 second
        sleep(1);

        // Set GPIO pins LOW
        gpioWrite(GPIO_17, 0);
        gpioWrite(GPIO_22, 0);
