#define PWM_PIN_3 22
#define PWM_PIN_4 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main()
{
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as PWM outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);
    gpioSetPWMfrequency(PWM_PIN_4, 1000);

    // Set PWM range (e.g., 1000 for 0-1000 duty cycle)
    gpioSetPWMrange(PWM_PIN_1, 1000);
    gpioSetPWMrange(PWM_PIN_2, 1000);
    gpioSetPWMrange(PWM_PIN_3, 1000);
    gpioSetPWMrange(PWM_PIN_4, 1000);

    // Main loop to set PWM duty cycles
    while (!terminate)
