        gpioPWM(PWM_PIN_1, 500);
        gpioPWM(PWM_PIN_2, 500);
        gpioPWM(PWM_PIN_3, 500);
        gpioPWM(PWM_PIN_4, 500);

        // Print the state to standard output
        printf("PWM_PIN_1: 500, PWM_PIN_2: 500, PWM_PIN_3: 500, PWM_PIN_4: 500\n");

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds

        // Set duty cycle to 0% (0 out of 1000)
        gpioPWM(PWM_PIN_1, 0);
        gpioPWM(PWM_PIN_2, 0);
        gpioPWM(PWM_PIN_3, 0);
        gpioPWM(PWM_PIN_4, 0);

        // Print the state to standard output
        printf("PWM_PIN_1: 0, PWM_PIN_2: 0, PWM_PIN_3: 0, PWM_PIN_4: 0\n");

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM outputs
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_1 2
#define GPIO_2 3

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_1, PI_OUTPUT);
    gpioSetMode(GPIO_2, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Set GPIO 2 HIGH, GPIO 3 LOW
        gpioWrite(GPIO_1, 1);
        gpioWrite(GPIO_2, 0);
        printf("GPIO %d: HIGH, GPIO %d: LOW\n", GPIO_1, GPIO_2);

        // Wait for 1 second
        sleep(1);

        // Set GPIO 2 LOW, GPIO 3 HIGH
        gpioWrite(GPIO_1, 0);
        gpioWrite(GPIO_2, 1);
        printf("GPIO %d: LOW, GPIO %d: HIGH\n", GPIO_1, GPIO_2);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and exit
    gpioWrite(GPIO_1, 0); // Ensure GPIO is LOW before exiting
    gpioWrite(GPIO_2, 0);
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

