int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 60;  // 60 seconds
    sleep_time.tv_nsec = 0;   // 0 nanoseconds

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
