#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_2, *line_3, *line_17;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_2) gpiod_line_release(line_2);
    if (line_3) gpiod_line_release(line_3);
    if (line_17) gpiod_line_release(line_17);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100ms

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_2 = gpiod_chip_get_line(chip, GPIO_2);
    line_3 = gpiod_chip_get_line(chip, GPIO_3);
    line_17 = gpiod_chip_get_line(chip, GPIO_17);

    if (!line_2 || !line_3 || !line_17) {
        perror("Error getting GPIO line");
        if (line_2) gpiod_line_release(line_2);
        if (line_3) gpiod_line_release(line_3);
        if (line_17) gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_2, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 2");
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_3, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 3");
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_17, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17");
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (int i = 0; i < 3; i++) {
        // Cycle 1: Set all pins HIGH
        ret = gpiod_line_set_value(line_2, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 2 value");
            break;
        }
        ret = gpiod_line_set_value(line_3, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 3 value");
            break;
        }
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 17 value");
            break;
        }
        printf("Cycle %d: GPIO 2=1, GPIO 3=1, GPIO 17=1\n", i + 1);
        nanosleep(&sleep_time, NULL);

        // Cycle 2: Set all pins LOW
        ret = gpiod_line_set_value(line_2, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 2 value");
            break;
        }
        ret = gpiod_line_set_value(line_3, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 3 value");
            break;
        }
        ret = gpiod_line_set_value(line_17, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 17 value");
            break;
        }
        printf("Cycle %d: GPIO 2=0, GPIO 3=0, GPIO 17=0\n", i + 1);
        nanosleep(&sleep_time, NULL);

        // Cycle 3: Set GPIO 2 HIGH, GPIO 3 LOW, GPIO 17 HIGH
        ret = gpiod_line_set_value(line_2, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 2 value");
            break;
        }
        ret = gpiod_line_set_value(line_3, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 3 value");
            break;
        }
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 17 value");
            break;
        }
        printf("Cycle %d: GPIO 2=1, GPIO 3=0, GPIO 17=1\n", i + 1);
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines
    gpiod_line_release(line_2);
    gpiod_line_release(line_3);
    gpiod_line_release(line_17);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

