// Define GPIO pins
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_12 12
#define GPIO_17 17

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_10, PI_OUTPUT);
    gpioSetMode(GPIO_11, PI_OUTPUT);
    gpioSetMode(GPIO_12, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);

    // Main loop to toggle GPIO states
    while (program_running) {
        // Set all GPIOs HIGH
        gpioWrite(GPIO_10, 1);
        gpioWrite(GPIO_11, 1);
        gpioWrite(GPIO_12, 1);
        gpioWrite(GPIO_17, 1);
        printf("GPIO 10: 1, GPIO 11: 1, GPIO 12: 1, GPIO 17: 1\n");
        sleep(1);

        // Set all GPIOs LOW
        gpioWrite(GPIO_10, 0);
        gpioWrite(GPIO_11, 0);
        gpioWrite(GPIO_12, 0);
        gpioWrite(GPIO_17, 0);
        printf("GPIO 10: 0, GPIO 11: 0, GPIO 12: 0, GPIO 17: 0\n");
        sleep(1);
    }

    // Clean up GPIO pins before exiting
    gpioWrite(GPIO_10, 0);
    gpioWrite(GPIO_11, 0);
    gpioWrite(GPIO_12, 0);
    gpioWrite(GPIO_17, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

