// Define the GPIO chip and line
#define GPIOCHIP "gpiochip0"
#define GPIO_LINE 27

// Define the validity check parameters
#define VALIDITY_CHECK_DELAY_NS 100000000 // 100 milliseconds

// Global variables for GPIO line and chip
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to perform the validity check
int perform_validity_check(struct gpiod_line *line) {
    struct timespec start, end;
    int value1, value2;

    // Read the initial value
    value1 = gpiod_line_get_value(line);
    if (value1 < 0) {
        fprintf(stderr, "Error reading initial value: %d\n", value1);
        return -1;
    }

    // Get the current time
    if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
        perror("clock_gettime");
        return -1;
    }

    // Wait for the specified delay
    struct timespec delay = {0, VALIDITY_CHECK_DELAY_NS};
    nanosleep(&delay, NULL);

    // Get the current time again
    if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
        perror("clock_gettime");
        return -1;
    }

    // Read the value after the delay
    value2 = gpiod_line_get_value(line);
    if (value2 < 0) {
        fprintf(stderr, "Error reading value after delay: %d\n", value2);
        return -1;
    }

    // Check if the values are the same
    if (value1 == value2) {
        return 0; // Valid
    } else {
        return -1; // Invalid
    }
}

int main() {
    int value;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    if (gpiod_line_request_output(line, "my-program", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set the GPIO output to HIGH
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value (HIGH)");
            break;
        }
        value = 1;
        printf("GPIO %d: HIGH\n", GPIO_LINE);

        // Perform the validity check
        if (perform_validity_check(line) == 0) {
            // Set the GPIO output to LOW
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("gpiod_line_set_value (LOW)");
                break;
            }
            value = 0;
            printf("GPIO %d: LOW\n", GPIO_LINE);
        } else {
            fprintf(stderr, "Validity check failed, leaving HIGH\n");
        }

        // Wait for 2 seconds
        sleep(2);
    }

    // Release the GPIO line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 1;
}

