#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define the GPIO chip and line
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18

// Define the validity check parameters
#define VALIDITY_CHECK_DELAY_NS 100000000 // 100 milliseconds

// Global variables for GPIO line and chip
static struct gpiod_line *line = NULL;
static struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
static volatile int keep_running = 1;

static void int_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to perform the validity check
int perform_validity_check(struct gpiod_line *line)
{
    int value1, value2;
    struct timespec ts;

    // Read the initial value
    value1 = gpiod_line_get_value(line);
    if (value1 < 0) {
        fprintf(stderr, "Error reading initial value: %s\n", strerror(errno));
        return -1;
    }

    // Wait for the specified delay
    ts.tv_sec = 0;
    ts.tv_nsec = VALIDITY_CHECK_DELAY_NS;
    if (nanosleep(&ts, NULL) != 0) {
        fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
        return -1;
    }

    // Read the value after the delay
    value2 = gpiod_line_get_value(line);
    if (value2 < 0) {
        fprintf(stderr, "Error reading value after delay: %s\n", strerror(errno));
        return -1;
    }

    // Check if the values are the same
    if (value1 != value2) {
        fprintf(stderr, "Validity check failed: values changed during delay.\n");
        return -1;
    }

    return 0;
}

int main()
{
    int value;
    struct timespec ts;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, int_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the GPIO line for output
    if (gpiod_line_request_output(line, "rpi_gpio_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Set the GPIO value to 1
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO value to 1: %s\n", strerror(errno));
            break;
        }

        // Perform the validity check
        if (perform_validity_check(line) < 0) {
            fprintf(stderr, "Validity check failed, skipping this iteration.\n");
            // Set the GPIO value back to 0 before continuing
            if (gpiod_line_set_value(line, 0) < 0) {
                fprintf(stderr, "Error setting GPIO value to 0: %s\n", strerror(errno));
                break;
            }
            continue; // Skip to the next iteration
        }

        // Read the GPIO value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
            break;
        }

        // Print the GPIO value
        printf("GPIO %d: %d\n", GPIO_LINE, value);

        // Wait for 5 seconds
        ts.tv_sec = 5;
        ts.tv_nsec = 0;
        if (nanosleep(&ts, NULL) != 0) {
            fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
            break;
        }

        // Set the GPIO value to 0
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO value to 0: %s\n", strerror(errno));
            break;
        }

        // Perform the validity check
        if (perform_validity_check(line) < 0) {
            fprintf(stderr, "Validity check failed, skipping this iteration.\n");
            continue; // Skip to the next iteration
        }

        // Read the GPIO value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
            break;
        }

        // Print the GPIO value
        printf("GPIO %d: %d\n", GPIO_LINE, value);

        // Wait for 5 seconds
        ts.tv_sec = 5;
        ts.tv_nsec = 0;
        if (nanosleep(&ts, NULL) != 0) {
            fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
            break;
        }
    }

    // Release the GPIO line and chip
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define MAX_SENSORS 10
#define MAX_SLAVES_DIR 256
#define MAX_W1_DEVICES 256
#define MAX_W1_SLAVES 256

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int find_sensors(char sensor_ids[][MAX_W1_DEVICES], int max_sensors) {
    DIR *dir;
    struct dirent *ent;
    int sensor_count = 0;

    dir = opendir("/sys/bus/w1/devices");
    if (dir == NULL) {
        perror("Error opening /sys/bus/w1/devices");
        return -1;
    }

    while ((ent = readdir(dir)) != NULL && sensor_count < max_sensors) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            strncpy(sensor_ids[sensor_count], ent->d_name, MAX_W1_DEVICES - 1);
            sensor_ids[sensor_count][MAX_W1_DEVICES - 1] = '\0'; // Ensure null termination
            sensor_count++;
        }
    }

    closedir(dir);
    return sensor_count;
}

int read_temperature(const char *sensor_id, float *temperature) {
    char filepath[MAX_SLAVES_DIR];
    int fd;
    char buffer[256];
    ssize_t bytes_read;
    char *token;
    float temp_value;

    snprintf(filepath, sizeof(filepath), "/sys/bus/w1/devices/%s/w1_slave", sensor_id);

    fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        perror("Error opening w1_slave file");
        return -1;
    }

    bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read == -1) {
        perror("Error reading w1_slave file");
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';

    close(fd);

    // Parse the temperature from the w1_slave output
    token = strstr(buffer, "t=");
    if (token == NULL) {
        fprintf(stderr, "Error: Temperature data not found in w1_slave output\n");
        return -1;
    }

    temp_value = strtof(token + 2, NULL);
    *temperature = temp_value / 1000.0;

    return 0;
}

int main() {
    char sensor_ids[MAX_SENSORS][MAX_W1_DEVICES];
    int sensor_count;
    int i;
    float temperature;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    signal(SIGINT, signal_handler);

    sensor_count = find_sensors(sensor_ids, MAX_SENSORS);
    if (sensor_count < 0) {
        fprintf(stderr, "Error finding sensors. Exiting.\n");
        return 1;
    } else if (sensor_count == 0) {
        fprintf(stderr, "No DS18B20 sensors found. Exiting.\n");
        return 1;
    }

    printf("Found %d DS18B20 sensors.\n", sensor_count);

    for (i = 0; i < sensor_count && program_running; i++) {
        printf("Reading temperature from sensor %s\n", sensor_ids[i]);
        if (read_temperature(sensor_ids[i], &temperature) == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s - Temperature: %.2f °C\n", timestamp, temperature);
        } else {
            fprintf(stderr, "Error reading temperature from sensor %s\n", sensor_ids[i]);
        }
        sleep(5);
    }

    printf("Exiting.\n");
    return 0;
}

