        // Set GPIO 17 HIGH, GPIO 18 LOW
        gpioWrite(GPIO_17, 1);
        gpioWrite(GPIO_18, 0);
        printf("GPIO 17: HIGH, GPIO 18: LOW\n");

        // Wait for 1 second
        sleep(1);

        // Set GPIO 17 LOW, GPIO 18 HIGH
        gpioWrite(GPIO_17, 0);
        gpioWrite(GPIO_18, 1);
        printf("GPIO 17: LOW, GPIO 18: HIGH\n");

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and exit
    gpioWrite(GPIO_17, 0); // Ensure GPIO is LOW before exiting
