#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define LED_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
long measure_pulse_width();
float calculate_distance(long pulse_width);
void set_led_state(int state);

// Signal handler for clean exit
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
    gpioWrite(LED_PIN, 0);      // Turn off LED initially

    return 0;
}

// Trigger the HC-SR04 sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width on the echo pin
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1);
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Set the LED state
void set_led_state(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("HC-SR04 sensor program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        // Calculate the distance
        float distance = calculate_distance(pulse_width);

        // Set the LED state
        if (distance > 0 && distance < 50) { // Object detected within 50cm
            set_led_state(1); // Turn on LED
        } else {
            set_led_state(0); // Turn off LED
        }

        // Print the distance
        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Invalid distance measurement\n");
        }

        // Wait 0.1 seconds
        gpioDelay(100); // 100ms
    }

    // Clean up GPIO
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

