        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to set the GPIO output
int set_gpio_output(int value) {
    int ret;
    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO output: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to perform the validity check
int perform_validity_check() {
    int ret;
    struct timespec delay = {0, VALIDITY_CHECK_DELAY_MS * 1000000L};

    for (int i = 0; i < VALIDITY_CHECK_RETRIES; ++i) {
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO input during validity check: %s\n", strerror(-ret));
            return -1;
        }
        if (ret == 0) {
            return 0; // Success
        }
        nanosleep(&delay, NULL);
    }
    fprintf(stderr, "Validity check failed after %d retries.\n", VALIDITY_CHECK_RETRIES);
    return -1; // Failure
}

int main() {
