    sleep_time.tv_sec = 1;  // 1 second
    sleep_time.tv_nsec = 0; // 0 nanoseconds

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the GPIO line for output
    ret = gpiod_line_request_output(line, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    for (cycle = 0; cycle < NUM_CYCLES; cycle++) {
        // Set the GPIO line to HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO line to HIGH");
            break;
        }
        printf("Cycle %d: GPIO %d set to HIGH\n", cycle + 1, GPIO_LINE);

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);

        // Set the GPIO line to LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO line to LOW");
            break;
        }
        printf("Cycle %d: GPIO %d set to LOW\n", cycle + 1, GPIO_LINE);

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Release the GPIO line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

