#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define PWM_PIN 4
#define DHT22_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define DHT22 data structure
typedef struct {
    unsigned char humidity_integer;
    unsigned char humidity_decimal;
    unsigned char temperature_integer;
    unsigned char temperature_decimal;
    unsigned char checksum;
} DHT22_Data;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read DHT22 data
int read_dht22(DHT22_Data *data) {
    int i, j;
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};

    // Set GPIO 22 as output
    gpioSetMode(DHT22_PIN, PI_OUTPUT);

    // Send start signal
    gpioWrite(DHT22_PIN, 0);
    gpioDelay(1);
    gpioWrite(DHT22_PIN, 1);
    gpioDelay(30);

    // Set GPIO 22 as input
    gpioSetMode(DHT22_PIN, PI_INPUT);

    // Wait for response (low for ~80us, high for ~80us)
    gpioDelay(80);
    if (gpioRead(DHT22_PIN) == 1) {
        fprintf(stderr, "DHT22: No response from sensor\n");
        return -1;
    }
    gpioDelay(80);
    if (gpioRead(DHT22_PIN) == 0) {
        fprintf(stderr, "DHT22: No response from sensor\n");
        return -1;
    }

    // Read 40 bits of data
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            // Wait for low
            while (gpioRead(DHT22_PIN) == 1);

            // Measure high time
            long start = gpioTick();
            while (gpioRead(DHT22_PIN) == 0);
            long end = gpioTick();

            // Determine bit value (0 if < 40us, 1 if >= 40us)
            if ((end - start) >= 40) {
                raw_data[i] |= (1 << (7 - j));
            }
        }
    }

    // Validate checksum
    if (((unsigned char)raw_data[0] + (unsigned char)raw_data[1] + (unsigned char)raw_data[2] + (unsigned char)raw_data[3]) != (unsigned char)raw_data[4]) {
        fprintf(stderr, "DHT22: Checksum error\n");
        return -1;
    }

    // Populate data structure
    data->humidity_integer = (unsigned char)raw_data[0];
    data->humidity_decimal = (unsigned char)raw_data[1];
    data->temperature_integer = (unsigned char)raw_data[2];
    data->temperature_decimal = (unsigned char)raw_data[3];
    data->checksum = (unsigned char)raw_data[4];

    return 0;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_pwm_duty_cycle(float temperature) {
    // Linear mapping: 0°C -> 0%, 30°C -> 100%
    int duty_cycle = (int)((temperature / 30.0) * 255.0);

    // Clamp duty cycle to 0-255 range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    return duty_cycle;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as PWM output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    DHT22_Data dht22_data;
    float temperature;
    int pwm_duty_cycle;

    // Main loop
    while (program_running) {
        // Read DHT22 data
        if (read_dht22(&dht22_data) == 0) {
            // Calculate temperature
            temperature = (float)(dht22_data.temperature_integer * 10 + dht22_data.temperature_decimal) / 10.0;

            // Calculate PWM duty cycle
            pwm_duty_cycle = calculate_pwm_duty_cycle(temperature);

            // Set PWM duty cycle
            gpioPWM(PWM_PIN, pwm_duty_cycle);

            // Print temperature and PWM duty cycle
            printf("Temperature: %.1f°C, PWM Duty Cycle: %d\n", temperature, pwm_duty_cycle);
        } else {
            fprintf(stderr, "Failed to read DHT22 data\n");
        }

        // Wait 0.1 seconds
        gpioDelay(100);
    }

    // Stop PWM output
    gpioPWM(PWM_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_PIN 4
#define LED_PIN 17

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read PIR sensor value
        int pir_value = gpioRead(PIR_PIN);

        // Check for motion detection
        if (pir_value == 1) {
            printf("Motion detected!\n");

            // Turn on LED
            gpioWrite(LED_PIN, 1);
            printf("LED ON\n");

            // Wait for 5 seconds
            gpioDelay(5000000); // 5 seconds in microseconds

            // Turn off LED
            gpioWrite(LED_PIN, 0);
            printf("LED OFF\n");
        }

        // Small delay to avoid busy-waiting
        gpioDelay(100000); // 0.1 seconds in microseconds
    }

    // Cleanup and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO chip and line
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4

// Define DHT22 data structure
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO
int init_gpio()
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "dht22_reader";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read DHT22 data
DHT22Data read_dht22()
{
    DHT22Data data = {0.0, 0.0, 0};
    int i, j;
    uint8_t raw_data[5] = {0};

    // Send start signal
    if (gpiod_line_set_direction(line, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        perror("Error setting GPIO line as output");
        return data;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line value");
        return data;
    }
    usleep(1000); // 1ms

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO line value");
        return data;
    }
    usleep(30); // 30us

    if (gpiod_line_set_direction(line, GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        perror("Error setting GPIO line as input");
        return data;
    }

    // Wait for response (low for 80us, high for 80us)
    usleep(80);
    if (gpiod_line_get_value(line) != 0) {
        fprintf(stderr, "DHT22 not responding (low)\n");
        return data;
    }
    usleep(80);
    if (gpiod_line_get_value(line) != 1) {
        fprintf(stderr, "DHT22 not responding (high)\n");
        return data;
    }
    usleep(80);

    // Read 40 bits (5 bytes)
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            // Wait for low
            while (gpiod_line_get_value(line) == 1) {
                // Timeout
                usleep(1000); // 1ms
                if (gpiod_line_get_value(line) == 0) break;
            }

            // Measure high time
            struct timespec start, end;
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(line) == 0) {
                // Timeout
                usleep(1000); // 1ms
                if (gpiod_line_get_value(line) == 1) break;
            }
            clock_gettime(CLOCK_MONOTONIC, &end);
            long time_diff = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

            // Determine if bit is 0 or 1
            if (time_diff > 40) {
                raw_data[i] |= (1 << (7 - j));
            }
        }
    }

    // Validate checksum
    if (raw_data[4] != ((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22 checksum error\n");
        return data;
    }

    // Convert data
    data.humidity = (float)(((uint16_t)raw_data[0] << 8) | raw_data[1]) / 10.0;
    data.temperature = (float)(((uint16_t)(raw_data[2] & 0x7F) << 8) | raw_data[3]) / 10.0;
    if (raw_data[2] & 0x80) {
        data.temperature *= -1.0;
    }
    data.valid = 1;

    return data;
}

// Function to print DHT22 data
void print_dht22_data(DHT22Data data)
{
    if (data.valid) {
        printf("Temperature: %.1f\u00b0C, Humidity: %.1f%%\n", data.temperature, data.humidity);
    } else {
        fprintf(stderr, "Invalid DHT22 data\n");
    }
}

// Function to cleanup GPIO
void cleanup_gpio()
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    // Main loop
    for (int i = 0; i < 3; i++) {
        DHT22Data data = read_dht22();
        print_dht22_data(data);
        sleep(2);
    }

    // Cleanup GPIO
    cleanup_gpio();

    return EXIT_SUCCESS;
}

