// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

// Function prototypes
int initialize_gpio();
void set_gpio_state(int gpio, int state);
void report_gpio_state(int gpio, int state);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to toggle GPIO states
    while (program_running) {
        // Toggle GPIO 17 and 22 to HIGH
        set_gpio_state(GPIO_17, 1);
        set_gpio_state(GPIO_22, 1);
        report_gpio_state(GPIO_17, 1);
        report_gpio_state(GPIO_22, 1);

        // Wait for 10 seconds
        sleep(10);

        // Toggle GPIO 23 and 24 to LOW
        set_gpio_state(GPIO_23, 0);
        set_gpio_state(GPIO_24, 0);
        report_gpio_state(GPIO_23, 0);
        report_gpio_state(GPIO_24, 0);

        // Wait for 10 seconds
        sleep(10);
    }

    // Cleanup GPIO pins before exiting
    cleanup_gpio();

    return 0;
}

// Function to initialize pigpio and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

