#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18

// Define the number of cycles
#define NUM_CYCLES 5

// Define the delay between cycles in milliseconds
#define CYCLE_DELAY_MS 50

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *line_4, *line_17, *line_18;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_4) {
        gpiod_line_release(line_4);
    }
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_18) {
        gpiod_line_release(line_18);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;
    struct timespec ts;
    int cycle;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_4 = gpiod_chip_get_line(chip, GPIO_4);
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_18 = gpiod_chip_get_line(chip, GPIO_18);

    if (!line_4 || !line_17 || !line_18) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_4, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 4");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line_17, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line_18, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (cycle = 0; cycle < NUM_CYCLES; cycle++) {
        // Set GPIO 4 high
        ret = gpiod_line_set_value(line_4, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 4 high");
            break;
        }
        printf("GPIO 4: 1\n");

        // Set GPIO 17 high
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 17 high");
            break;
        }
        printf("GPIO 17: 1\n");

        // Set GPIO 18 high
        ret = gpiod_line_set_value(line_18, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 18 high");
            break;
        }
        printf("GPIO 18: 1\n");

        // Delay
        ts.tv_sec = 0;
        ts.tv_nsec = CYCLE_DELAY_MS * 1000000;
        nanosleep(&ts, NULL);

        // Set GPIO 4 low
        ret = gpiod_line_set_value(line_4, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 4 low");
            break;
        }
        printf("GPIO 4: 0\n");

        // Set GPIO 17 low
        ret = gpiod_line_set_value(line_17, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 17 low");
            break;
        }
        printf("GPIO 17: 0\n");

        // Set GPIO 18 low
        ret = gpiod_line_set_value(line_18, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 18 low");
            break;
        }
        printf("GPIO 18: 0\n");

        // Delay
        ts.tv_sec = 0;
        ts.tv_nsec = CYCLE_DELAY_MS * 1000000;
        nanosleep(&ts, NULL);
    }

    // Release GPIO lines
    gpiod_line_release(line_4);
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

