#define GPIO_22  22
#define GPIO_23  23
#define GPIO_24  24
#define GPIO_25  25
#define GPIO_27  27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio, int state)
{
    int result = gpioWrite(gpio, state);
    if (result != 0) {
        fprintf(stderr, "Error setting GPIO %d to state %d: %d\n", gpio, state, result);
        return -1; // Indicate an error
    }
    return 0; // Indicate success
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set the GPIO pins as outputs
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);
    gpioSetMode(GPIO_25, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to control the GPIO pins
    for (int i = 0; i < 100 && !terminate; ++i) {
        // Set all GPIOs HIGH
        if (set_gpio_state(GPIO_4, 1) != 0 ||
            set_gpio_state(GPIO_17, 1) != 0 ||
            set_gpio_state(GPIO_22, 1) != 0 ||
            set_gpio_state(GPIO_23, 1) != 0 ||
            set_gpio_state(GPIO_24, 1) != 0 ||
            set_gpio_state(GPIO_25, 1) != 0 ||
            set_gpio_state(GPIO_27, 1) != 0) {
            break; // Exit loop on error
        }
        printf("Cycle %d: GPIOs HIGH\n", i + 1);
        gpioDelay(500000); // Wait 0.5 seconds

        // Set all GPIOs LOW
        if (set_gpio_state(GPIO_4, 0) != 0 ||
            set_gpio_state(GPIO_17, 0) != 0 ||
            set_gpio_state(GPIO_22, 0) != 0 ||
            set_gpio_state(GPIO_23, 0) != 0 ||
            set_gpio_state(GPIO_24, 0) != 0 ||
            set_gpio_state(GPIO_25, 0) != 0 ||
            set_gpio_state(GPIO_27, 0) != 0) {
            break; // Exit loop on error
        }
        printf("Cycle %d: GPIOs LOW\n", i + 1);
        gpioDelay(500000); // Wait 0.5 seconds
    }

    // Clean up and exit
    gpioTerminate();
    if (terminate) {
        return 0; // Exit normally on termination signal
    } else {
        return 0; // Exit normally after 100 cycles
    }
}

