#define PWM_RANGE 1000

// Define PWM frequency (adjust as needed)
#define PWM_FREQUENCY 1000 // Hz

// Define cycle duration
#define CYCLE_DURATION 60   // seconds

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop
    for (int cycle = 0; cycle < 5 && program_running; cycle++) {
        // Cycle 1: 100% duty cycle
        printf("Cycle %d: 100%% duty cycle\n", cycle + 1);
        gpioPWM(PWM_PIN_1, PWM_RANGE);
        gpioPWM(PWM_PIN_2, PWM_RANGE);
        gpioPWM(PWM_PIN_3, PWM_RANGE);
        gpioPWM(PWM_PIN_4, PWM_RANGE);
        sleep(CYCLE_DURATION);

        // Cycle 2: 50% duty cycle
        printf("Cycle %d: 50%% duty cycle\n", cycle + 1);
        gpioPWM(PWM_PIN_1, PWM_RANGE / 2);
        gpioPWM(PWM_PIN_2, PWM_RANGE / 2);
        gpioPWM(PWM_PIN_3, PWM_RANGE / 2);
        gpioPWM(PWM_PIN_4, PWM_RANGE / 2);
        sleep(CYCLE_DURATION);

        // Cycle 3: 0% duty cycle
        printf("Cycle %d: 0%% duty cycle\n", cycle + 1);
        gpioPWM(PWM_PIN_1, 0);
        gpioPWM(PWM_PIN_2, 0);
        gpioPWM(PWM_PIN_3, 0);
        gpioPWM(PWM_PIN_4, 0);
        sleep(CYCLE_DURATION);

        // Cycle 4: 75% duty cycle
        printf("Cycle %d: 75%% duty cycle\n", cycle + 1);
        gpioPWM(PWM_PIN_1, PWM_RANGE * 3 / 4);
        gpioPWM(PWM_PIN_2, PWM_RANGE * 3 / 4);
        gpioPWM(PWM_PIN_3, PWM_RANGE * 3 / 4);
        gpioPWM(PWM_PIN_4, PWM_RANGE * 3 / 4);
        sleep(CYCLE_DURATION);

        // Cycle 5: 25% duty cycle
        printf("Cycle %d: 25%% duty cycle\n", cycle + 1);
        gpioPWM(PWM_PIN_1, PWM_RANGE / 4);
        gpioPWM(PWM_PIN_2, PWM_RANGE / 4);
        gpioPWM(PWM_PIN_3, PWM_RANGE / 4);
        gpioPWM(PWM_PIN_4, PWM_RANGE / 4);
        sleep(CYCLE_DURATION);
    }

    // Cleanup and exit
    printf("Cleaning up and exiting...\n");
    gpioTerminate();
    return 0;
}

