// Define GPIO pins for PWM outputs
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23
#define PWM_PIN_5 24
#define PWM_PIN_6 25

// Define PWM range (0-1000)
#define PWM_RANGE 1000

// Define PWM frequency (e.g., 1000 Hz)
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as PWM outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);
    gpioSetMode(PWM_PIN_6, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_5, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_6, PWM_RANGE);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_5, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_6, PWM_FREQUENCY);

    // Main loop to control PWM outputs
    while (!terminate) {
        // Set PWM duty cycle for each pin
        gpioPWM(PWM_PIN_1, 0);   // 0%
        gpioPWM(PWM_PIN_2, 250);  // 25%
        gpioPWM(PWM_PIN_3, 500);  // 50%
        gpioPWM(PWM_PIN_4, 750);  // 75%
        gpioPWM(PWM_PIN_5, 1000); // 100%
        gpioPWM(PWM_PIN_6, 500);  // 50%

        // Print the state to standard output
        printf("PWM_PIN_1: 0, PWM_PIN_2: 250, PWM_PIN_3: 500, PWM_PIN_4: 750, PWM_PIN_5: 1000, PWM_PIN_6: 500\n");

        // Wait for 0.05 seconds
        usleep(50000); // 50000 microseconds = 0.05 seconds

        // Set PWM duty cycle for each pin
        gpioPWM(PWM_PIN_1, 1000); // 100%
        gpioPWM(PWM_PIN_2, 750);  // 75%
        gpioPWM(PWM_PIN_3, 250);  // 25%
        gpioPWM(PWM_PIN_4, 0);    // 0%
        gpioPWM(PWM_PIN_5, 500);  // 50%
        gpioPWM(PWM_PIN_6, 500);  // 50%

        // Print the state to standard output
        printf("PWM_PIN_1: 1000, PWM_PIN_2: 750, PWM_PIN_3: 250, PWM_PIN_4: 0, PWM_PIN_5: 500, PWM_PIN_6: 500\n");

        // Wait for 0.05 seconds
        usleep(50000); // 50000 microseconds = 0.05 seconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
