int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;  // 1 second
    sleep_time.tv_nsec = 0; // 0 nanoseconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_23 = gpiod_chip_get_line(chip, GPIO_23);
    line_24 = gpiod_chip_get_line(chip, GPIO_24);

    if (!line_17 || !line_23 || !line_24) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_17, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_23, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 23");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_24, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 24");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO states
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 17 value");
            break;
        }

        ret = gpiod_line_set_value(line_23, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 23 value");
            break;
