        ret = gpiod_line_set_value(line_24, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 24 value");
            break;
        }

        // Print GPIO states
        printf("GPIO 17: 1, GPIO 23: 0, GPIO 24: 1\n");

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);

        // Toggle GPIO states
        ret = gpiod_line_set_value(line_17, 0);
        if (ret < 0) {
            perror("Error setting GPIO line 17 value");
            break;
        }

        ret = gpiod_line_set_value(line_23, 1);
        if (ret < 0) {
            perror("Error setting GPIO line 23 value");
            break;
        }

