    gpiod_line_release(line_17);
    gpiod_line_release(line_23);
    gpiod_line_release(line_24);
    gpiod_chip_close(chip);

    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define DHT22_PIN 4
#define LED_PIN 17

// Define constants
#define MAX_TIMINGS 85
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *dht22_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_dht22(int gpio_pin, float *temperature, float *humidity);
int validate_data(int data[], int length);
void signal_handler(int sig);
int gpio_init(int dht22_pin, int led_pin);
void gpio_cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize GPIO lines
int gpio_init(int dht22_pin, int led_pin) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    dht22_line = gpiod_chip_get_line(chip, dht22_pin);
    if (!dht22_line) {
        perror("Error getting DHT22 line");
        gpiod_chip_close(chip);
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, led_pin);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_line_release(dht22_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "dht22_led", 0) < 0) {
        perror("Error requesting LED line for output");
        gpiod_line_release(dht22_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(dht22_line, "dht22_input") < 0) {
        perror("Error requesting DHT22 line for input");
        gpiod_line_release(led_line);
        gpiod_line_release(dht22_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO resources
void gpio_cleanup(void) {
    if (dht22_line) {
        gpiod_line_release(dht22_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Read data from DHT22 sensor
int read_dht22(int gpio_pin, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_count = 0;
    struct timespec start, end;
    long pulse_length;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Send start signal
        if (gpiod_line_set_value(dht22_line, 0) < 0) {
            perror("Error setting DHT22 line to low");
            return -1;
        }
        usleep(1000); // 1 ms

        if (gpiod_line_set_value(dht22_line, 1) < 0) {
            perror("Error setting DHT22 line to high");
            return -1;
        }
        usleep(30); // 30 us

        // Prepare to read data
        if (gpiod_line_set_value(dht22_line, 0) < 0) {
            perror("Error setting DHT22 line to low");
            return -1;
        }
        usleep(40); // 40 us

        // Read data
        for (int i = 0; i < MAX_TIMINGS; i++) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(dht22_line) == 0) {
                clock_gettime(CLOCK_MONOTONIC, &end);
                pulse_length = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
                if (pulse_length > 2000) {
                    fprintf(stderr, "Timeout waiting for DHT22 response.\n");
                    goto retry;
                }
            }

            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(dht22_line) == 1) {
                clock_gettime(CLOCK_MONOTONIC, &end);
                pulse_length = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
                if (pulse_length > 2000) {
                    fprintf(stderr, "Timeout waiting for DHT22 response.\n");
                    goto retry;
                }
            }

            clock_gettime(CLOCK_MONOTONIC, &end);
            pulse_length = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

            if (pulse_length > 50) {
                data[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
            }
            bit_count++;
        }

        // Validate data
        if (validate_data(data, 5)) {
            *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
            *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
            if (data[2] & 0x80) {
                *temperature *= -1.0;
            }
            return 0; // Success
        } else {
            fprintf(stderr, "Data validation failed.\n");
        }

    retry:
        retries++;
        if (retries < MAX_RETRIES) {
            fprintf(stderr, "Retrying DHT22 read (%d/%d)...\n", retries, MAX_RETRIES);
            usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read DHT22 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Validate data integrity
int validate_data(int data[], int length) {
    if (length != 5) {
        return 0;
    }

    int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        return 0;
    }

    return 1;
}

int main() {
    float temperature, humidity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    int cycle_count = 0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(DHT22_PIN, LED_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    // Main loop
    while (cycle_count < 3 && !terminate) {
        // Read DHT22 data
        if (read_dht22(DHT22_PIN, &temperature, &humidity) == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print data to standard output
            printf("%s, Temperature: %.1f C, Humidity: %.1f %%\n", timestamp, temperature, humidity);

            // Turn on LED for 1 second
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("Error setting LED line to high");
            }
            usleep(1000000); // 1 second
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("Error setting LED line to low");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 data.\n");
        }

        // Wait 60 seconds
        sleep(60);
        cycle_count++;
    }

    // Cleanup GPIO resources
    gpio_cleanup();

    printf("Program terminated.\n");
    return 0;
}

