#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to initialize SPI
int spi_init() {
    int fd;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from MAX31855
int read_max31855(int fd, uint8_t *data) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = 0, // No transmit buffer
        .rx_buf = (unsigned long)data,
        .len = 4, // Read 4 bytes
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    return 0;
}

// Function to process the raw data and extract temperature
float process_data(uint8_t *data) {
    int16_t raw_temp = (data[0] << 8) | data[1];
    raw_temp >>= 2; // Shift right by 2 bits

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "Fault detected: Open circuit.\n");
        return -273.15; // Return absolute zero as error value
    } else if (data[3] & 0x02) {
        fprintf(stderr, "Fault detected: Short to GND.\n");
        return -273.15;
    } else if (data[3] & 0x04) {
        fprintf(stderr, "Fault detected: Short to VCC.\n");
        return -273.15;
    }

    return (float)raw_temp * 0.25;
}

int main() {
    uint8_t data[4];
    float temperature;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Read data from MAX31855
    if (read_max31855(spi_fd, data) < 0) {
        fprintf(stderr, "Failed to read data from MAX31855. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Process the data
    temperature = process_data(data);

    // Print the temperature
    if (temperature != -273.15) {
        printf("Temperature: %.2f °C\n", temperature);
    } else {
        fprintf(stderr, "Error reading temperature.\n");
    }

    // Close SPI device
    close(spi_fd);

    return 0;
}

