float measure_distance(gpio_config_t config) {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(config.trigger_pin, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(config.trigger_pin, 0);

    // Measure echo pulse width
    start_tick = gpioTick();
    while (gpioRead(config.echo_pin) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0; // Timeout error
        }
    }
    start_tick = gpioTick();

    end_tick = gpioTick();
    while (gpioRead(config.echo_pin) == 1) {
        if (gpioTick() - end_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0; // Timeout error
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpio_config_t gpio_config = {TRIGGER_PIN, ECHO_PIN};

    gpioSetMode(gpio_config.trigger_pin, PI_OUTPUT);
    gpioSetMode(gpio_config.echo_pin, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(gpio_config.trigger_pin, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        float distance = measure_distance(gpio_config);

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Could not measure distance\n");
        }

        gpioDelay(100); // Delay between measurements
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

