// BMP280 I2C address
#define BMP280_I2C_ADDR 0x03

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read a single byte from an I2C register
int read_register(int fd, uint8_t reg_addr, uint8_t *value) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return 0;
}

// Function to write a single byte to an I2C register
int write_register(int fd, uint8_t reg_addr, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP280
int read_calibration_data(int fd, struct bmp280_calib_data *calib) {
    uint8_t buffer[24];
    uint8_t reg_addr = BMP280_REG_CALIB_00;

    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write calibration register address");
        return -1;
    }
    if (read(fd, buffer, 24) != 24) {
        perror("Failed to read calibration data");
        return -1;
    }

    calib->dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib->dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib->dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib->dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib->dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib->dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib->dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib->dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib->dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib->dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib->dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib->dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data
int read_raw_data(int fd, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t buffer[6];
    uint8_t reg_addr = BMP280_REG_PRESS_MSB;

    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write raw data register address");
        return -1;
    }
    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read raw data");
        return -1;
    }

    *raw_press = ((int32_t)buffer[0] << 12) | ((int32_t)buffer[1] << 4) | ((int32_t)buffer[2] >> 4);
    *raw_temp = ((int32_t)buffer[3] << 12) | ((int32_t)buffer[4] << 4) | ((int32_t)buffer[5] >> 4);

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temp, struct bmp280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)raw_temp) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temp) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temp) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_press, struct bmp280_calib_data calib, double t_fine) {
    double var1, var2, p;
    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // Standard I2C device on Raspberry Pi
    int retries = 3;
    int i;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Check if the device is present by reading a register
    uint8_t chip_id;
    if (read_register(i2c_fd, BMP280_REG_RESET, &chip_id) != 0) {
        fprintf(stderr, "BMP280 not found at address 0x%02X\n", BMP280_I2C_ADDR);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &calib) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set the BMP280 to forced mode
    if (write_register(i2c_fd, BMP280_REG_CTRL_MEAS, 0b00100011) != 0) { // Oversampling x1, forced mode
        fprintf(stderr, "Failed to set forced mode\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    for (i = 0; i < 3; i++) {
        int32_t raw_temp, raw_press;
        double temperature, pressure;

        // Read raw data
        if (read_raw_data(i2c_fd, &raw_temp, &raw_press) != 0) {
            fprintf(stderr, "Failed to read raw data, retrying...\n");
            sleep(1); // Wait before retrying
            i--; // Retry the same iteration
            continue;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temp, calib);
        pressure = compensate_pressure(raw_press, calib, temperature);

        // Print the results
        printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
