#include <unistd.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

// Function prototypes
void set_gpio_output(int gpio, int level);
void report_gpio_state(int gpio);
void cleanup_handler(int signum);

// Global variable to track program state for cleanup
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void cleanup_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signum);

    // Set all GPIOs to low before exiting
    set_gpio_output(GPIO_17, 0);
    set_gpio_output(GPIO_22, 0);
    set_gpio_output(GPIO_23, 0);
    set_gpio_output(GPIO_24, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to set the output level of a GPIO pin
void set_gpio_output(int gpio, int level) {
    gpioWrite(gpio, level);
}

// Function to report the state of a GPIO pin
void report_gpio_state(int gpio) {
    int state = gpioRead(gpio);
    printf("GPIO %d: %s\n", gpio, (state == 1) ? "HIGH" : "LOW");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);

    // Set initial state (all HIGH)
    set_gpio_output(GPIO_17, 1);
    set_gpio_output(GPIO_22, 1);
    set_gpio_output(GPIO_23, 1);
    set_gpio_output(GPIO_24, 1);

    // Report initial state
    report_gpio_state(GPIO_17);
    report_gpio_state(GPIO_22);
    report_gpio_state(GPIO_23);
    report_gpio_state(GPIO_24);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, cleanup_handler);

    // Keep the program running until a signal is caught
    while (program_running) {
        sleep(1); // Sleep for 1 second
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define the GPIO chip and line
#define GPIOCHIP "gpiochip0"
#define GPIO_LINE 18

// Define the number of readings
#define NUM_READINGS 5

// Define the validity check threshold
#define THRESHOLD 0.5

// Global variables for GPIO line and chip
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to read the GPIO line
int read_gpio(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to calculate the average of the readings
double calculate_average(int readings[], int num_readings) {
    double sum = 0.0;
    for (int i = 0; i < num_readings; i++) {
        sum += readings[i];
    }
    return sum / num_readings;
}

// Function to check if the average is valid
int is_valid(double average, double threshold) {
    return (average >= 0.0 && average <= 1.0) && (average >= 0.0 + threshold || average <= 1.0 - threshold);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for input
    if (gpiod_line_request_input(line, "gpio_control") < 0) {
        perror("Error requesting GPIO line for input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Read the GPIO line multiple times
    int readings[NUM_READINGS];
    for (int i = 0; i < NUM_READINGS; i++) {
        readings[i] = read_gpio(line);
        if (readings[i] == -1) {
            fprintf(stderr, "Error reading GPIO, exiting.\n");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }
        usleep(10000); // 10ms delay
    }

    // Calculate the average
    double average = calculate_average(readings, NUM_READINGS);

    // Check if the average is valid
    if (is_valid(average, THRESHOLD)) {
        printf("Average: %.2f, State: %d\n", average, (int)(average > 0.5));
    } else {
        fprintf(stderr, "Invalid reading: Average = %.2f\n", average);
    }

    // Release the GPIO line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO chip and line
#define GPIOCHIP "gpiochip0"
#define GPIO_LINE 17

// Define validity check parameters
#define VALIDITY_CHECK_DELAY_MS 100
#define VALIDITY_CHECK_THRESHOLD_MS 50

// Global variables for GPIO line and chip
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to set the GPIO output
int set_gpio_output(int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO output: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to perform the validity check
int perform_validity_check(int initial_value) {
    struct timespec start, end;
    int new_value;

    // Set the GPIO to the opposite value
    if (set_gpio_output(!initial_value) < 0) {
        return -1;
    }

    // Wait for the specified delay
    usleep(VALIDITY_CHECK_DELAY_MS * 1000); // Convert ms to microseconds

    // Read the GPIO value
    new_value = gpiod_line_get_value(line);
    if (new_value < 0) {
        fprintf(stderr, "Error reading GPIO value during validity check: %d\n", new_value);
        return -1;
    }

    // Record the current time
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Set the GPIO back to the initial value
    if (set_gpio_output(initial_value) < 0) {
        return -1;
    }

    // Wait for the specified delay
    usleep(VALIDITY_CHECK_DELAY_MS * 1000); // Convert ms to microseconds

    // Record the current time
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate the time difference in milliseconds
    long elapsed_time_ms = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;

    // Check if the time difference is within the threshold
    if (elapsed_time_ms > VALIDITY_CHECK_THRESHOLD_MS) {
        fprintf(stderr, "Validity check failed: Elapsed time = %ld ms\n", elapsed_time_ms);
        return -1;
    }

    return 0;
}

int main() {
    int initial_value;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    if (gpiod_line_request_output(line, "gpio-control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Read the initial GPIO value
    initial_value = gpiod_line_get_value(line);
    if (initial_value < 0) {
        fprintf(stderr, "Error reading initial GPIO value: %d\n", initial_value);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Perform the validity check
    if (perform_validity_check(initial_value) < 0) {
        fprintf(stderr, "Validity check failed, exiting\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO output to the opposite value
    if (set_gpio_output(!initial_value) < 0) {
        fprintf(stderr, "Error setting GPIO output to opposite value\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Read the GPIO value again
    int final_value = gpiod_line_get_value(line);
    if (final_value < 0) {
        fprintf(stderr, "Error reading final GPIO value: %d\n", final_value);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Print the final GPIO value
    printf("GPIO %d: %d\n", GPIO_LINE, final_value);

    // Release the GPIO line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

