    uint8_t reg = BME280_REG_CTRL_HUM;
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (write(fd, &ctrl_hum, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    reg = BME280_REG_CTRL_MEAS;
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (write(fd, &ctrl_meas, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    reg = BME280_REG_CONFIG;
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (write(fd, &config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for the measurement to complete (adjust delay as needed)
    usleep(100000); // 100ms

    // Read the data
    reg = BME280_REG_PRESSURE_MSB;
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (read(fd, buffer, 8) != 8) {
        perror("Error reading from I2C device");
        return -1;
    }

    *pressure = (int32_t)buffer[0] << 12 | (int32_t)buffer[1] << 4 | (int32_t)buffer[2] >> 4;
    *temperature = (int32_t)buffer[3] << 12 | (int32_t)buffer[4] << 4 | (int32_t)buffer[5] >> 4;
    *humidity = (int32_t)buffer[6] << 8 | (int32_t)buffer[7];

    return 0;
}

