// VEML7700 I2C address
#define VEML7700_ADDR 0x10

// VEML7700 register addresses
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS 0x04
#define VEML7700_WHITE 0x05
#define VEML7700_POWER_SAVE 0x06

// Configuration values
#define ALS_CONF_DEFAULT 0x0000 // Integration time = 100ms, Gain = 1

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to a VEML7700 register
int veml7700_write_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = value & 0xFF;
    buf[2] = (value >> 8) & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from a VEML7700 register
int veml7700_read_register(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (buf[1] << 8) | buf[0];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure VEML7700
    if (veml7700_write_register(i2c_fd, VEML7700_ALS_CONF, ALS_CONF_DEFAULT) < 0) {
        fprintf(stderr, "Failed to configure VEML7700\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t als_data;

        // Read ALS data
        if (veml7700_read_register(i2c_fd, VEML7700_ALS, &als_data) < 0) {
            fprintf(stderr, "Failed to read ALS data\n");
            break; // Exit loop on error
        }

        // Get current time
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        // Print data
        printf("%s, ALS: %u\n", buf, als_data);

        // Wait 0.5 seconds
        usleep(500000); // 0.5 seconds = 500000 microseconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

