#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 400.0     // Maximum valid distance in cm
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to end
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        float distance = measure_distance();

        if (distance > 0 && distance <= MAX_DISTANCE) {
            // Get current time
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print distance with timestamp
            printf("%s Distance: %.2f cm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(500000); // Wait 0.5 seconds (500000 microseconds)
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the GPIO chip and line number
#define GPIOCHIP "gpiochip0"
#define GPIO_LINE 8

// Global variables for GPIO line and chip
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    if (gpiod_line_request_output(line, "rpi_gpio_control", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to toggle the GPIO state
    while (1) {
        // Set the GPIO line to HIGH
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Error setting GPIO line to HIGH");
            break;
        }
        printf("GPIO %d: HIGH\n", GPIO_LINE);

        // Wait for 0.001 seconds
        struct timespec delay = {0, 1000000}; // 1 millisecond
        nanosleep(&delay, NULL);

        // Set the GPIO line to LOW
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Error setting GPIO line to LOW");
            break;
        }
        printf("GPIO %d: LOW\n", GPIO_LINE);

        // Wait for 0.001 seconds
        nanosleep(&delay, NULL);
    }

    // Clean up resources before exiting
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 1;
}

