        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (write_register(i2c_fd, POWER_CTL, 0x08) < 0) { // Enable measurement mode
        fprintf(stderr, "Failed to set POWER_CTL register\n");
        close(i2c_fd);
        return 1;
    }
    if (write_register(i2c_fd, DATA_FORMAT, 0x08) < 0) { // +/- 2g range
        fprintf(stderr, "Failed to set DATA_FORMAT register\n");
        close(i2c_fd);
        return 1;
    }

    // Read accelerometer data
    uint8_t data[6];
    if (read_registers(i2c_fd, DATAX0, data, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        close(i2c_fd);
        return 1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t x = (int16_t)((data[1] << 8) | data[0]);
    int16_t y = (int16_t)((data[3] << 8) | data[2]);
    int16_t z = (int16_t)((data[5] << 8) | data[4]);

    // Print the readings
    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

