#define GPIO_18  18
#define GPIO_22  22
#define GPIO_23  23
#define GPIO_24  24
#define GPIO_25  25
#define GPIO_27  27

// Array of GPIO pins
int gpio_pins[] = {GPIO_4, GPIO_17, GPIO_18, GPIO_22, GPIO_23, GPIO_24, GPIO_25, GPIO_27};
int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Set all GPIOs to low before exiting
    for (int i = 0; i < num_pins; i++) {
        gpioWrite(gpio_pins[i], 0);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    for (int i = 0; i < num_pins; i++) {
        gpioSetMode(gpio_pins[i], PI_OUTPUT);
    }

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Set all GPIOs to HIGH
        for (int i = 0; i < num_pins; i++) {
            gpioWrite(gpio_pins[i], 1);
            printf("Setting GPIO %d HIGH\n", gpio_pins[i]);
        }
        usleep(50000); // 0.05 seconds

        // Set all GPIOs to LOW
        for (int i = 0; i < num_pins; i++) {
            gpioWrite(gpio_pins[i], 0);
            printf("Setting GPIO %d LOW\n", gpio_pins[i]);
        }
        usleep(50000); // 0.05 seconds
    }

    // The program should never reach here, but it's good practice to include
    gpioTerminate();
    return 0;
}

