#define GPIO_27 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_4, *line_17, *line_27;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_4) {
        gpiod_line_release(line_4);
    }
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_27) {
        gpiod_line_release(line_27);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_4 = gpiod_chip_get_line(chip, GPIO_4);
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_27 = gpiod_chip_get_line(chip, GPIO_27);

    if (!line_4 || !line_17 || !line_27) {
        perror("Error getting GPIO line");
        goto cleanup;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_4, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 4");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line_17, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line_27, "app", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 27");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Get current time
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        // Set GPIO values
        gpiod_line_set_value(line_4, 1);
        gpiod_line_set_value(line_17, 0);
        gpiod_line_set_value(line_27, 1);

        // Print state to standard output
        printf("%s: GPIO 4: %d, GPIO 17: %d, GPIO 27: %d\n", buf, 1, 0, 1);

        // Wait for 0.5 seconds
        usleep(500000);

        // Toggle GPIO values
        gpiod_line_set_value(line_4, 0);
        gpiod_line_set_value(line_17, 1);
        gpiod_line_set_value(line_27, 0);

        // Print state to standard output
        now = time(NULL);
        tstruct = localtime(&now);
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
        printf("%s: GPIO 4: %d, GPIO 17: %d, GPIO 27: %d\n", buf, 0, 1, 0);

        // Wait for 0.5 seconds
        usleep(500000);
    }

cleanup:
    // Release GPIO lines
    if (line_4) {
        gpiod_line_release(line_4);
    }
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_27) {
        gpiod_line_release(line_27);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1;
}

