#define PWM_FREQUENCY 1000

// Define the PWM range (resolution)
#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pin as an output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set the PWM frequency
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);

    // Set the PWM range
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to control the PWM output
    while (!terminate)
    {
        // Set the PWM duty cycle to 0 (off)
        gpioPWM(PWM_PIN, 0);
        printf("PWM: 0\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds

        // Set the PWM duty cycle to 500 (50% duty cycle)
        gpioPWM(PWM_PIN, 500);
        printf("PWM: 500\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds

        // Set the PWM duty cycle to 1000 (100% duty cycle)
        gpioPWM(PWM_PIN, 1000);
        printf("PWM: 1000\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Stop the PWM output
    gpioPWM(PWM_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

