int main() {
    int ret;
    int cycle_count = 0;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100ms

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line_4) {
        perror("Error getting GPIO line 4");
        gpiod_chip_close(chip);
        return 1;
    }

    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line_17) {
        perror("Error getting GPIO line 17");
        gpiod_line_release(line_4);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_4, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 4 for output");
        gpiod_line_release(line_4);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_17, "gpio-control", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 for output");
        gpiod_line_release(line_4);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (cycle_count < 5) {
        // Set GPIO 4 high, GPIO 17 low
        ret = gpiod_line_set_value(line_4, 1);
        if (ret < 0) {
            perror("Error setting GPIO 4 high");
            break;
        }
        ret = gpiod_line_set_value(line_17, 0);
        if (ret < 0) {
            perror("Error setting GPIO 17 low");
            break;
        }
        printf("Cycle %d: GPIO 4 = HIGH, GPIO 17 = LOW\n", cycle_count + 1);

        // Wait 100ms
        nanosleep(&sleep_time, NULL);

        // Set GPIO 4 low, GPIO 17 high
        ret = gpiod_line_set_value(line_4, 0);
        if (ret < 0) {
            perror("Error setting GPIO 4 low");
            break;
        }
        ret = gpiod_line_set_value(line_17, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 high");
            break;
        }
        printf("Cycle %d: GPIO 4 = LOW, GPIO 17 = HIGH\n", cycle_count + 1);

        // Wait 100ms
        nanosleep(&sleep_time, NULL);

        cycle_count++;
    }

    // Cleanup
    gpiod_line_release(line_4);
    gpiod_line_release(line_17);
    gpiod_chip_close(chip);

    return 0;
}

