#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO chip and line
#define GPIOCHIP "gpiochip0"
#define GPIO_LINE 24

// Define validity check parameters
#define VALIDITY_CHECK_DELAY_MS 100
#define VALIDITY_CHECK_THRESHOLD_MS 50

// Global variables for GPIO line and chip
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Function to set the GPIO output
int set_gpio_output(int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO output: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to read the GPIO input with validity check
int read_gpio_input() {
    int value1, value2;
    struct timespec start, end;
    long elapsed_time_ms;

    // Read the initial value
    value1 = gpiod_line_get_value(line);
    if (value1 < 0) {
        fprintf(stderr, "Error reading GPIO input (first read): %d\n", value1);
        return -1;
    }

    // Wait for a short delay
    usleep(VALIDITY_CHECK_DELAY_MS * 1000); // Convert ms to microseconds

    // Read the value again
    value2 = gpiod_line_get_value(line);
    if (value2 < 0) {
        fprintf(stderr, "Error reading GPIO input (second read): %d\n", value2);
        return -1;
    }

    // Check if the values are the same
    if (value1 != value2) {
        fprintf(stderr, "Invalid reading: values differ.\n");
        return -1;
    }

    // Check for consistent reading over a period
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            fprintf(stderr, "Error reading GPIO input (consistency check): %d\n", current_value);
            return -1;
        }
        if (current_value != value1) {
            fprintf(stderr, "Invalid reading: inconsistent reading.\n");
            return -1;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_time_ms = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;
        if (elapsed_time_ms >= VALIDITY_CHECK_THRESHOLD_MS) {
            break;
        }
        usleep(1000); // Check every 1ms
    }

    return value1;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "gpio-control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO output to HIGH
    if (set_gpio_output(1) < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO %d set to HIGH\n", GPIO_LINE);

    // Read GPIO input
    int input_value = read_gpio_input();
    if (input_value < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO %d read: %d\n", GPIO_LINE, input_value);

    // Set GPIO output to LOW
    if (set_gpio_output(0) < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    printf("GPIO %d set to LOW\n", GPIO_LINE);

    // Release GPIO line and close chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

