void report_gpio_state(int gpio, int state) {
    printf("GPIO %d: %s\n", gpio, (state == 1) ? "HIGH" : "LOW");
}

int main() {
    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(GPIO_0, PI_OUTPUT);
    gpioSetMode(GPIO_1, PI_OUTPUT);
    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_5, PI_OUTPUT);
    gpioSetMode(GPIO_12, PI_OUTPUT);
    gpioSetMode(GPIO_17, PI_OUTPUT);

    // Main loop to control the GPIO pins
    while (!terminate) {
        // Set all GPIOs HIGH
        if (set_gpio_state(GPIO_0, 1) != 0 ||
            set_gpio_state(GPIO_1, 1) != 0 ||
            set_gpio_state(GPIO_2, 1) != 0 ||
            set_gpio_state(GPIO_3, 1) != 0 ||
            set_gpio_state(GPIO_4, 1) != 0 ||
            set_gpio_state(GPIO_5, 1) != 0 ||
            set_gpio_state(GPIO_12, 1) != 0 ||
            set_gpio_state(GPIO_17, 1) != 0) {
            terminate = 1; // Exit loop on error
            break;
        }

        // Report the state of each GPIO
        report_gpio_state(GPIO_0, 1);
        report_gpio_state(GPIO_1, 1);
        report_gpio_state(GPIO_2, 1);
        report_gpio_state(GPIO_3, 1);
        report_gpio_state(GPIO_4, 1);
        report_gpio_state(GPIO_5, 1);
        report_gpio_state(GPIO_12, 1);
        report_gpio_state(GPIO_17, 1);

        // Wait for 1 second
        sleep(1);

        // Set all GPIOs LOW
        if (set_gpio_state(GPIO_0, 0) != 0 ||
            set_gpio_state(GPIO_1, 0) != 0 ||
            set_gpio_state(GPIO_2, 0) != 0 ||
            set_gpio_state(GPIO_3, 0) != 0 ||
            set_gpio_state(GPIO_4, 0) != 0 ||
            set_gpio_state(GPIO_5, 0) != 0 ||
            set_gpio_state(GPIO_12, 0) != 0 ||
            set_gpio_state(GPIO_17, 0) != 0) {
            terminate = 1; // Exit loop on error
            break;
        }

        // Report the state of each GPIO
        report_gpio_state(GPIO_0, 0);
        report_gpio_state(GPIO_1, 0);
        report_gpio_state(GPIO_2, 0);
        report_gpio_state(GPIO_3, 0);
        report_gpio_state(GPIO_4, 0);
        report_gpio_state(GPIO_5, 0);
        report_gpio_state(GPIO_12, 0);
        report_gpio_state(GPIO_17, 0);

        // Wait for 1 second
        sleep(1);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

