#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LED_PIN 27

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int pulse_duration = 0;
static volatile int distance = 0;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioTerminate();
    exit(0);
}

// Function to send a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
    } else if (level == 0) {
        pulse_end = tick;
        pulse_duration = pulse_end - pulse_start;
        distance = pulse_duration / 58; // Speed of sound is approximately 343 m/s, which is 58 us per cm

        // Validate distance
        if (distance > 0 && distance < 400) {
            printf("Distance: %d cm\n", distance);
            gpioWrite(LED_PIN, 1); // Turn on LED
            gpioDelay(500);         // Wait 500ms
            gpioWrite(LED_PIN, 0); // Turn off LED
        } else {
            printf("Invalid distance reading: %d cm\n", distance);
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 sensor program running. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(500); // Delay between measurements
    }

    // Cleanup (should not reach here if signal handler works)
    gpioTerminate();
    return 0;
}

