#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout

// Global variable for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance in centimeters
float measure_distance()
{
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    long long timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0; // Indicate timeout error
        }
    }
    start_tick = gpioTick();

    // Wait for echo to end
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeout_start > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0; // Indicate timeout error
        }
    }
    end_tick = gpioTick();

    // Calculate pulse duration
    diff_tick = end_tick - start_tick;

    // Calculate distance
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2

    return distance;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        float distance = measure_distance();

        if (distance > 0)
        {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Could not measure distance\n");
        }

        gpioDelay(100000); // 0.1 seconds
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

