#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Enable Register Values
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02

// Integration Time
#define TCS34725_INTEGRATIONTIME_2_4MS  0xFF   /* 2.4ms - 1 cycle    - Max Count: 1024  */

// Gain
#define TCS34725_GAIN_60X  0x03   /* 60x gain */

int i2c_fd;
volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int tcs34725_init(int fd) {
    // Enable power and ALS
    if (i2c_write_byte(fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    usleep(3000); // Wait for power-on
    if (i2c_write_byte(fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;

    // Set integration time
    if (i2c_write_byte(fd, TCS34725_COMMAND_BIT | TCS34725_ATIME, TCS34725_INTEGRATIONTIME_2_4MS) < 0) return -1;

    // Set gain
    if (i2c_write_byte(fd, TCS34725_COMMAND_BIT | TCS34725_CONTROL, TCS34725_GAIN_60X) < 0) return -1;

    return 0;
}

int tcs34725_read_raw(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[8];

    if (i2c_read_bytes(fd, TCS34725_COMMAND_BIT | TCS34725_CDATA, data, 8) < 0) return -1;

    *clear = data[0] | (data[1] << 8);
    *red   = data[2] | (data[3] << 8);
    *green = data[4] | (data[5] << 8);
    *blue  = data[6] | (data[7] << 8);

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // Standard I2C device on Raspberry Pi
    uint8_t device_address = TCS34725_ADDRESS;
    uint16_t clear, red, green, blue;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 0.5 seconds

    signal(SIGINT, signal_handler);

    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, device_address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 sensor initialized. Reading data...\n");

    while (program_running) {
        if (tcs34725_read_raw(i2c_fd, &clear, &red, &green, &blue) == 0) {
            printf("Clear: %5u, Red: %5u, Green: %5u, Blue: %5u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    close(i2c_fd);
    printf("I2C device closed. Exiting.\n");
    return EXIT_SUCCESS;
}

