        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Set PWM duty cycle to 50%
        gpioPWM(PWM_PIN_1, PWM_RANGE / 2);
        gpioPWM(PWM_PIN_2, PWM_RANGE / 2);
        gpioPWM(PWM_PIN_3, PWM_RANGE / 2);

        // Print PWM state
        printf("PWM on GPIO %d: %d\n", PWM_PIN_1, PWM_RANGE / 2);
        printf("PWM on GPIO %d: %d\n", PWM_PIN_2, PWM_RANGE / 2);
        printf("PWM on GPIO %d: %d\n", PWM_PIN_3, PWM_RANGE / 2);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds

        // Set PWM duty cycle to 0%
        gpioPWM(PWM_PIN_1, 0);
        gpioPWM(PWM_PIN_2, 0);
        gpioPWM(PWM_PIN_3, 0);

        // Print PWM state
        printf("PWM on GPIO %d: %d\n", PWM_PIN_1, 0);
        printf("PWM on GPIO %d: %d\n", PWM_PIN_2, 0);
        printf("PWM on GPIO %d: %d\n", PWM_PIN_3, 0);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

