#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define LED_PIN 24

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04
float measure_distance()
{
    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse width
    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) // Timeout after 10ms
    {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000)
    {
        fprintf(stderr, "Error: Echo pulse start timeout\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 30000) // Timeout after 30ms (max pulse width)
    {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 30000)
    {
        fprintf(stderr, "Error: Echo pulse end timeout\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    // Calculate pulse width in microseconds
    uint32_t pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    // distance = (pulse_width * 0.000001) * 34300 / 2
    // Simplified: distance = pulse_width * 0.01715
    float distance = pulse_width * 0.01715;

    return distance;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Measure distance
        float distance = measure_distance();

        // Check for errors
        if (distance < 0)
        {
            fprintf(stderr, "Error: Distance measurement failed\n");
        } else {
            // Print distance to standard output
            printf("Distance: %.2f cm\n", distance);

            // Control LED based on distance
            if (distance < 10)
            {
                gpioWrite(LED_PIN, 1); // Turn LED on
            } else
            {
                gpioWrite(LED_PIN, 0); // Turn LED off
            }
        }

        // Delay before next measurement
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio

    return 0;
}

