#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_23, PI_OUTPUT);
    gpioSetMode(GPIO_24, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Set GPIO pins HIGH
        gpioWrite(GPIO_18, 1);
        gpioWrite(GPIO_23, 1);
        gpioWrite(GPIO_24, 1);
        printf("GPIO %d: HIGH, GPIO %d: HIGH, GPIO %d: HIGH\n", GPIO_18, GPIO_23, GPIO_24);

        // Wait for 0.1 seconds
        time_sleep(0.1);

        // Set GPIO pins LOW
        gpioWrite(GPIO_18, 0);
        gpioWrite(GPIO_23, 0);
        gpioWrite(GPIO_24, 0);
        printf("GPIO %d: LOW, GPIO %d: LOW, GPIO %d: LOW\n", GPIO_18, GPIO_23, GPIO_24);

        // Wait for 0.1 seconds
        time_sleep(0.1);
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_GYRO_XOUT_H 0x43

// I2C device file
#define I2C_DEV "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_i2c_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_i2c_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to register");
        return -1;
    }
    return 0;
}

// Function to read accelerometer and gyroscope data
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buf[14];
    uint8_t reg = MPU6050_REG_ACCEL_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for bulk read");
        return -1;
    }

    if (read(fd, buf, 14) != 14) {
        perror("Failed to read accelerometer and gyroscope data");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    if (write_i2c_reg(i2c_fd, MPU6050_REG_PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

        // Read accelerometer and gyroscope data
        if (read_mpu6050_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Get current time
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

            // Print the data
            printf("%s, Accel: X=%6d, Y=%6d, Z=%6d, Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   buf, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read MPU6050 data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define the GPIO chip and line
#define GPIOCHIP "gpiochip0"
#define GPIO_LINE 17

// Global variables for GPIO line and chip
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 600000000; // 0.6 seconds

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    ret = gpiod_line_request_output(line, "my-program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Set the GPIO line to HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO line to HIGH");
            break;
        }
        printf("GPIO %d: HIGH\n", GPIO_LINE);

        // Sleep for 0.6 seconds
        nanosleep(&sleep_time, NULL);

        // Set the GPIO line to LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO line to LOW");
            break;
        }
        printf("GPIO %d: LOW\n", GPIO_LINE);

        // Sleep for 0.6 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up resources before exiting
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 1;
}
